2. 본문 성경 읽기(3번)

3. 반복 단어 찾기(형광펜 사용 추천):

고넬료: 31절 33절 

베드로: 32절 33절 34절 

구제/의를 행함/선한 일: 31절 35절 38절

복음/전파된 그것: 36절 37절

기억/다 받으시는 줄: 31절 35절

4. 주제 만들기: 

복음 전파의 깨우침을 받은 베드로.

5. 하나님 찾기 (관찰)

 구제를 기억하시는 하나님.

죽으시고 다시 살아나신 예수.

 

6.인간 찾기(관찰)

이방인 중에 하나님을 경외하는 사람도 동일하게 하나님이 받아주심.

7. 하나님 찾기(해석)

베드로는 이방인 백 부장 고넬료를 만난 후 깨우침을 받았다. 

그가 알게 된 사실은 복음은 이스라엘 백성뿐만 아니라 자신 민족을 핍박하는 로마, 그리고 온 세상 민족도 포함된다는 사실이었다. 

그것이 바로 하나님의 뜻이었다. 특별히 하나님은 이방인이라고 하더라도 하나님을 경외하고 선을 베풀고 구제를 하는 사람은 기억하신다는 것을 새롭게 깨우쳤다. 

여기서 ''기억''하시는 하나님의 속성을 생각하면 지금 우리가 행하는 선행이나 기도 또는 복음 전파하는 모든 일들을 하나님은 알고 계신다. 

다만 때가 되면 모든 행위가 열매로 드러나며 하나님이 응답하신다는 사실에 큰 위로를 받는다. 

현재 우리 남 청년(남북 청년 연합선교회)이 행하고 기도로 준비하는 모든 일들 또한 언젠가는 빛을 비추는 날들의 오기를 기대한다. 

설령 마지막 때가 먼저 오더라도 사후세계에서라도 반드시 보상받은 것을 믿는다. 

그러므로 하나님을 절대 믿고 의지하며 순종해야겠다. 또한 하나님의 일을 제한해서는 결코 안 되겠다.

8. 인간 찾기(해석)

9. 적용

하나님을 제한하지 말기. 주님이 명령하시면 믿고 순종하기. 

오늘 아침에 전도한 대상자 놓고 간절히 기도해야겠다.

10. 영적 터치 (단어 또는 구절)

네 구제를 기억하셨으니

11. 믿음과 회개 및 감사기도로 마무리

12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);
INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-01-03', '사도행전', '10장 41~48절', '부활의 재판장 되신 예수.', '(사도행전 10장)

41. 모든 백성에게 하신 것이 아니요 오직 미리 택하신 증인 곧 죽은 자 가운데서 부활하신 후 그를 모시고 음식을 먹은 우리에게 하신 것이라

42. 우리에게 명하사 백성에게 전도하되 하나님이 살아 있는 자와 죽은 자의 재판장으로 정하신 자가 곧 이 사람인 것을 증언하게 하셨고

43. 그에 대하여 모든 선지자도 증언하되 그를 믿는 사람들이 다 그의 이름을 힘입어 죄 사함을 받는다 하였느니라

44.  베드로가 이 말을 할 때에 성령이 말씀 듣는 모든 사람에게 내려오시니

45. 베드로와 함께 온 할례 받은 신자들이 이방인들에게도 성령 부어 주심으로 말미암아 놀라니

46. 이는 방언을 말하며 하나님 높임을 들음이러라

47. 이에 베드로가 이르되 이 사람들이 우리와 같이 성령을 받았으니 누가 능히 물로 세례 베풂을 금하리요 하고

48. 명하여 예수 그리스도의 이름으로 세례를 베풀라 하니라 그들이 베드로에게 며칠 더 머물기를 청하니라

