8. 인간 찾기(해석)

헤롯은 즉시 죽었다. 그것도 비참하게 벌레들에 의하여 죽임을 당했다. 

마치 지옥 속에 고통당하는 한 장면을 보는 듯하다. 죽기 전에 헤롯은 왕복을 입고 나름 멋진 연설을 하였다. 

그의 연설은 얼마나 잘 준비되고 듣는 백성들을 잘 설득하고 선동하는 내용이었는지 백성들은 이구동성으로 말했다. "이것은 신의 소리 요 사람의 소리가 아니라" 말하였다.

그때 헤롯은 교만하여 영광을 하나님께 올리지 않았다. 

 즉시 하나님은 천사를 보내어 그를 쳤다. 

간단한 내용 속에 진정한 왕이 누구인지 알 수 있다. 

헤롯은 왕으로서 세상의 권세와 인기 부귀를 가진 자였다. 

하지만 하나님 앞에서는 보잘것없이 쓰러지는 인간임을 볼 수 있다. 진정한 왕은 하나님 한 분이시다. 

이러한 모습을 볼 때 안개같이 사라지는 세상의 욕망을 버리고 실체이신 하나님의 영광을 위하여 사는 삶이야말로 복된 인생이 확실하다. 

비록 세상에서는 알아주는 사람 없는 무명인이라도 그가 하나님 앞에 겸손한 사람이면 이미 그는 천국을 소유한 사랍니다. 

우리 남 청년(남북 청년 연합선교회) 회원 모두 이러한 사실을 알고 모두 그렇게 살았으면 좋겠다.

