6.인간 찾기(관찰)

- 구약 성경 말씀으로 설명하며 복음을 선포하는 바울

- 바울에게 다음 안식일에도 말씀을 전해달라 요청하는 유대인과 유대교에 입교한 경건한 사람들

- 바울의 말을 듣고 기뻐하는 이방인들

- 바울의 말에 반박하는 비방하는 유대인들

- 지역 유력자들을 선동하여 바울과 바나바를 추방하는 유대인들

- 기쁨과 성령으로 충만한 제자들 

7.하나님 찾기(해석)

8.인간 찾기(해석)

- 바울이 유대인들이 복음을 받아들이기를 바라며 말씀을 선포한다.

- 많은 유대인과 유대교에 입교한 경건한 사람들이 그 말씀을 더 듣기 원하기도 하지만,

- 어떤 유대인들(아마도 많은 수의 유대인들)은 바울을 시기하여 반대하고 비방한다.

- 바울은 이 유대인들이 복음을 못 알아듣는 자가 되지 않기를 바랬지만,

- 이들은 도무지 믿지 못할 것이라는 성경(41절)을 응하게 하는 역할을 하게 되었다.

- 바울과 바나바는 해도 받고 추방을 당하였지만, 복음이 열매 맺고 자라가는 모습을 보며 매우 기뻤을 것이다.

- 제자들 또한 기쁨과 성령이 충만하여 기뻐했다.

- 성령 충만과 기쁨은 같은 말이 아니지만 같이 오는 것으로 보인다.

- 성령이 충만하면 비록 박해를 받더라도 하나님의 뜻이 이루어지는 것을 볼 수 있고, 하나님의 뜻이 이루어지는 것을 보면 기쁨이 넘치게 되는 것이다.

 

9.적용(나) 

- 부활하신 예수님께서 베드로와 제자들에게 나타나시고,

- 그 제자들과 바울, 바나바가 이방인에게도 복음을 전하게 하시고,

- 그들의 제자들이 복음을 전하게 하시고,

- 그 복음이 내게도 전해지게 하시고,

- 나를 통해 또 다른 사람들이 복음을 듣게 하시는 이 모든 계획과 섭리에 감사를 드린다.

- 이해할 수 없는 하나님의 사랑과 지혜에 감사를 드리며 오늘 하루 성령님을 의지하여 기쁨으로 살아야겠다.

