- 예루살렘(2,4절)

4. 주제만들기: 편견 없는 복음

5. 하나님 찾기 (관찰)

- 마음을 아시는 하나님, 성령을 주셔서 증언하심

- 유대인과 이방인을 차별하지 않으시는 하나님

6. 인간 찾기 (관찰)

- 바울과 바나바과 모세의 율법과 할례 문제로 어떤 사람들과 다툼을 함

- 이 문제에 대해 예루살렘에 있는 사도와 장로들에게 의논하고자 바울과 바나바를 보냄

- 베니게와 사마리아로 다니며 이방인이 주께 돌아온 것을 말함. 형제들이 기뻐함

- 예루살렘에서 사도와 장로들이 이 일을 두고 논의함

- 베드로는 복음의 말씀을 믿게 하시려고 자신을 택해 증언하게 했다고 말함

7. 하나님 찾기 (해석)

- 하나님의 때는 단계적으로 이루어진다. 유대인으로부터 이방인까지 복음을 전파되었고, 그 과정은 하나님의 때에 이루어졌다. 

- 하나님의 사랑은 차별이 없음을 보여준다.

- 예수님의 희생으로부터 시작된 복음은 차별 없이 누구에게나 전달되어야 한다.

8. 인간(해석):

- 당시 유대인들은 복음이 자신들만의 것으로 생각하는 경우가 당연했다.

- 그러나 베드로와 바울, 바나바를 통해 복음은 더 이상 유대인의 것이 아니라 이방인에게도 전해져야 함을 깨닫게 된다.

- 이 과정을 설득할 수 있는 근거는 성령님이다. 즉 예수님이 이 땅에 오시지 않았더라면 우리의 굳은 마음을 변화시킬 근거는 만들어지지 않았다. 

- 예수님을 통해 우리에게 주어진 성령은 하나님의 말씀을 바르게 해석할 수 있는 통찰력을 주었다. 

- 성령님을 의지하며 지혜롭게 남북청년연합 선교회 사역을 만들어가길 소망한다.

9. 적용(나): 

- 조건 없이 주어진 복음을 흘려보내도록 전도에 더욱 시간을 쓸 수 있길 기도해야겠다.

10. 영적터치(단어/구절)

- 성령을 주어 증언하시고

11. 믿음과 회개 및 감사기도로 마무리

12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);
INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-01-19', '사도행전', '15장 21~30절', '편지를 전달하는 바울과 바나바와 형제들', '(사도행전 15장)

21. 이는 예로부터 각 성에서 모세를 전하는 자가 있어 안식일마다 회당에서 그 글을 읽음이라 하더라

22. 이에 사도와 장로와 온 교회가 그중에서 사람들을 택하여 바울과 바나바와 함께 안디옥으로 보내기를 결정하니 곧 형제 중에 인도자인 바사바라 하는 유다와 실라더라

23. 그 편에 편지를 부쳐 이르되 사도와 장로 된 형제들은 안디옥과 수리아와 길리기아에 있는 이방인 형제들에게 문안하노라

24. 들은즉 우리 가운데서 어떤 사람들이 우리의 지시도 없이 나가서 말로 너희를 괴롭게 하고 마음을 혼란하게 한다 하기로

25. 사람을 택하여 우리 주 예수 그리스도의 이름을 위하여 생명을 아끼지 아니하는 자인 우리가 사랑하는 바나바와 바울과 함께 너희에게 보내기를 만장일치로 결정하였노라

27. 그리하여 유다와 실라를 보내니 그들도 이 일을 말로 전하리라

28. 성령과 우리는 이 요긴한 것들 외에는 아무 짐도 너희에게 지우지 아니하는 것이 옳은 줄 알았노니

29. 우상의 제물과 피와 목매어 죽인 것과 음행을 멀리할지니라 이에 스스로 삼가면 잘되리라 평안함을 원하노라 하였더라

30. 그들이 작별하고 안디옥에 내려가 무리를 모은 후에 편지를 전하니

3331 생명의 큐티

3:하나님, 인간, 나

3:관찰, 해석, 적용

3:반복 단어 찾기, 질문하기, 대상이 되어봄(본문)

1:감동하는 단어나 구절 찾기(영적 터치)

2025년 10월 22일

사도행전 15장 21절~30절

1.1분기도

2. 본문 성경 읽기(3번)

3. 반복 단어 찾기(형광펜 사용 추천):

택하여: 22절, 25절

바울과 바나바: 21절 22절 25절

결정: 22절 25절

편지를 부쳐/편지를 전하니: 23절 30절

전하리라/전하니: 27절 30절

4. 주제 만들기:

편지를 전달하는 바울과 바나바와 형제들

5. 하나님 찾기 (관찰)

질서를 잡아주시는 성령님

6. 인간 찾기(관찰)

예루살렘 교회의 사도와 장로로부터 안디옥교회로 보냄을 받은 바울과 바나바와 유다와 실라. (그들은  받은 편지를 전달함)

7. 하나님 찾기(해석)

8. 인간 찾기(해석)

초대교회는 영적 질서가 자리 잡고 있음을 알 수 있다.

구원과 관련해서 논쟁(이방인의 모세의 율법과 할례)이 있었을 때 안디옥교회에 있던 바울과 바나바는 예루살렘 교회의 영적 권위를 인정하고 받아들였다.

예루살렘 교회의 출발은 사도나 장로로부터  시작된 것은 아니었다.

분명한 성령 체험을 허락하신 성령 하나님의 인도하심인 것을 깨우친다.

베드로와 바울 그리고 바나바는 이방인에 대한 구원에 대하여 각각 성령 하나님의 인도하심을 경험하였다.

그럴 뿐만 아니라 그 외 사림들도 그와 같은 음성을 들었다.

28절에 보면 "성령과 우리는" 기록된 것처럼 모두가 성령님을 의존하고 있음을 본다.

영적 질서는 각 교회 목사님으로부터 출발하는 것이 아니라 성령 하나님의 권능으로부터 시작된다.

우리 남 청년(남북 청년 연합선교회)도 마찬가지로 성령님의 주권으로 질서가 잡힌다.

성령 하나님은 한 성령님으로서 혼란과 분열을 막으시고 공동체와 개인에게 안정과 평안하게 해 주심을 알 수 있다.

그분은 우리 공동체의 주인이시고 왕이시다. 또한 그분은 흠이 없으시고 완벽하시다.

이러한 모습을 보면 성령 충만함을 위하여 노력하는 삶이야말로 선택이 아닌 의무요 신자의 특권임을 깨우친다.

9. 적용

오늘도 성령 충만함을 받기 위하여 더욱 간구해야겠다.

10. 영적 터치 (단어 또는 구절)

28절: 성령과 우리는 이 요긴한 것들 외에는 아무 짐도 너희에게 지우지 아니하는

11. 믿음과 회개 및 감사기도로 마무리

12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);
INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-01-20', '사도행전', '15장 11~20절', '이방인의 구원에 대한 예루살렘 교회의 공인', '사도행전 15장

11   그러나 우리는 그들이 우리와 동일하게 주 예수의 은혜로 구원 받는 줄을 믿노라 하니라

12   온 무리가 가만히 있어 바나바와 바울이 하나님께서 자기들로 말미암아 이방인 중에서 행하신 표적과 기사에 관하여 말하는 것을 듣더니

13   말을 마치매 야고보가 대답하여 이르되 형제들아 내 말을 들으라

14   하나님이 처음으로 이방인 중에서 자기 이름을 위할 백성을 취하시려고 그들을 돌보신 것을 시므온이 말하였으니

15   선지자들의 말씀이 이와 일치하도다 기록된 바

16   이 후에 내가 돌아와서 다윗의 무너진 장막을 다시 지으며 또 그 허물어진 것을 다시 지어 일으키리니

17   이는 그 남은 사람들과 내 이름으로 일컬음을 받는 모든 이방인들로 주를 찾게 하려 함이라 하셨으니

18   즉 예로부터 이것을 알게 하시는 주의 말씀이라 함과 같으니라

19   그러므로 내 의견에는 이방인 중에서 하나님께로 돌아오는 자들을 괴롭게 하지 말고

20   다만 우상의 더러운 것과 음행과 목매어 죽인 것과 피를 멀리하라고 편지하는 것이 옳으니

