5.하나님 찾기(관찰)

6.인간 찾기(관찰)

- 베드로가 이방인도 주의 은혜로 구원받는 다고 선포함

- 바나바와 바울이 하나님께서 자기들로 말미암아 이방인 중에서 행하신 표적과 기사에 관하여 말함

- 베드로와 바나바, 바울의 말을 듣고 구원에 대해 생각하는 제자들

- 베드로가 말한 고넬료 이야기와 구약 말씀을 근거로 이방인에게도 구원이 있음을 인정하는 야고보 

7.하나님 찾기(해석)

8.인간 찾기(해석)

- 제자들도 주의 은혜로 구원을 받았으니 이방인도 주의 은혜로 구원을 받는 것이라고 정확히 선포하는 베드로

- 성령님께서 역사하셔서 베드로에게 이 믿음과 확신이 생겼고 용기를 내어 담대하게 선포했다.

- 바나바와 바울도 힘을 얻어 하나님께서 자신들을 통해 이방인들에게 역사하셨음을 선포

- 이 자리는 예루살렘 교회 지도자와 할례파들이 모인 자리로 이방인도 구원받는 다는 사실을 선포하기에 부담이 있었을 것임

- 그러나 성령님께서 역사하셨기에 베드로, 바나바, 바울은 담대히 말할 수 있었음.

- 세 사람의 선포와 증언을 들은 야고보가 이방인에게도 구원임하는 것을 인정하고 예루살렘 교회에 공식적으로 선포함

- 이것은 구원은 율법을 지키는 행위에서 오는 것이 아니라 오직 주 예수 그리스도를 믿음으로 구원이 임한다는 것을 공식적으로 선포한 예루살렘 교회의 아주 중요한 선포이다.

9.적용(나) 

- 나의 의지와 능력, 또는 힘과 선행이 아니라, 

- 내가 죄인 됨에도 불구하고 찾아와 주시고 구원하여 주신,

- 주 예수 그리스도의 은혜로 말미암아 나는 주님을 믿었고 구원을 받았다.

- 이것을 기억하고 나의 모든 시공간 속에서 주를 의지하고 그의 능력을 힘입어 살아야 한다.

10.영적 터치(단어/구절)

