- 하나님의 말씀에 붙잡혀 예수를 그리스도라 전하는 바울

- 대적하는 고린도 사람들

- 하나님을 경외하는 디도의 집으로 들어가서 지내며 회당장 그리스보에게 복음을 전하는 바울

- 환상을 보는 바울

7. 하나님 찾기 (해석)

- 혼자 외로이 긴 시간 복음을 전하는 바울에게 하나님은 두려워말라고 말씀하셨다.

- 바울에게 얼마나 큰 위로가 되었을까?

- 하나님께선 우리를 방치하지 않으신다. 우리를 위로하시며, 담대하게 하시며, 용기를 주는 분이시다.  

8. 인간(해석):

- 복음을 들은 사람들 중 복음을 받아들인 사람이 있고, 대적한 사람들이 있다. 

- 복음을 받아들인 사람들은 그들이 특별해서 복음을 받아들인 것은 아니다. 모든 것은 하나님의 은혜이다.

- 그러므로 우리는 복음을 받아들일 수 있음에 감사하고, 다른 이에게 복음을 전할 수 있어야한다. 

- 복음을 받아들이지 못한 사람들에겐 긍휼한 마음이 생겨야한다. 그들이 안타까워야하며, 하나님의 때에 복음을 받아들이길 간절히 기도할 수 있어야 한다.

- 복음을 전하고 긍휼한 마음을 가질 수 있길 소망한다.

9. 적용(나):

- 노방전도를 꾸준히 이어가고, 믿지 않는 사람을 위해 기도해야겠다. 

