6.인간 찾기(관찰)

- 아시아의 관리들이 바울이 극장에 가지 말라고 권함

- 극장에 모인 사람들이 극장에 왜 모였는지 자세히 알지는 못함

- 유대인들이 알렉산더를 권하여 말하게 하나 에베소 사람들이 듣지 않고,

- 두 시간 동안 에베소 사람의 아데미여 라고 외침

- 에베소의 서기장이 무리를 진정시키고 설득하여 해산시킴

7.하나님 찾기(해석)

8.인간 찾기(해석)

- 아시아의 관리들이 바울에게 극장에 가지 말라고 한 것을 보면 극장의 분위기가 얼마나 험악했는지 추측해 볼 수 있다

- 극장에 모인 사람들은 자신들의 생업이 위기에 처하자 모인 사람들로 정확히 무슨 일로 모였는지 알지는 못했다

- 이들은 자신들이 연구한 책들을 불태운 마술사들과 상반되는 모습을 보이는데, 이들이 마술사들이 본 기적을 함께 보았는지는 정확히 알 수는 없으나,

- 이들에게 믿음이 없었다는 것은 확실해 보인다.

- 이들과 비교할 때 마술사들이 자신들의 책을 불태운 것이 얼마나 큰 사건인지 알 수 있다.

- 유대인 알렉산더가 무리를 설득하려 하나 군중심리로 인해 흥분한 무리를 진정시킬 수가 없었고 오히려 더욱 흥분하여 소리지르게 하였다

- 에베소의 서기장이 무리들에게 이 모임의 명분이 없음과 오히려 책망받을 수 있음을 경고하고 나서야 무리가 흩어짐 

- 무리에게 잡혀갔던 가이오와 아리스다고가 어떤 수모를 당했는지는 알 수 없으나, 

- 서기장이 무리를 제지하고 해산하게 하여 큰 일을 당하지는 않은 것으로 보인다

9.적용(나) 

- 복음 전도자는 핍박을 당하고 하는데, 예측하지 못한 공격을 당하기도 하며, 모함을 받기도  한다.

- 극장에 모인 무리들을 보면, 복음 전도자를 왜 공격하는지 알지도 못하면서 공격하는 이들도 있다.

- 복음 전도자는 이런 것을 잘 기억하고 어떻게 대처해야 할지 한 번쯤 고민해 봐야 할 것이다.

