13.  우리는 앞서 배를 타고 앗소에서 바울을 태우려고 그리로 가니 이는 바울이 걸어서 가고자 하여 그렇게 정하여 준 것이라

14. 바울이 앗소에서 우리를 만나니 우리가 배에 태우고 미둘레네로 가서

