2025년 11월 08일

사도행전 20장 11절~20절

1.1분기도

2. 본문 성경 읽기(3번)

3. 반복 단어 찾기(형광펜 사용 추천):

앗소: 13절 14절 

배를 타고/태우려고: 13절 14절 16절

지체하지 않기 위하여/급히: 16절

가니/가고자/감이러라: 13절 16절

밀레도: 15절 17절

4. 주제 만들기:

급히 예루살렘으로 가려 하는 바울.

5. 하나님 찾기 (관찰)

6. 인간 찾기(관찰)

다시 살아난 유두고의 일로 피차 위로받는 사람들.

드로아에서 앗소까지 도보로 움직인 바울.

누가와 동역자들은 배로 이동함.

앗소에서 바울을 포함하여 배로 이동.

에베소 장로들을 밀레도로 청한 바울.

그동안 눈물과 겸손으로 수고했던 사역을 나누는 바울.

 7. 하나님 찾기(해석)

8. 인간 찾기(해석)

사도바울은 드로아 에서 앗소까지 걸어갔다. 사도행전 저자인 누가와 다른 동역자들과 함께 배를 탈 수도 있었는데 그렇게 했다. 

드로아에서 앗소까지 약 30km이고 도보로는 7시간 이상 걸리는 길이다. 

사도바울이 일부러 해안 길을 걸은 것 보면 개인적으로 깊은 묵상과 결단을 내리기 위함을 추측할 수 있다. 

사실 사도바울은 오순절 행사를 위하여 예루살렘 가기 위하여 서두른 것을 보면 이제는 바울도 마지막 길인 것을 직감한 듯하다. 

그러므로 바울은 에베소에 있는 장로를 그곳으로 오라고 청한 것을 알 수 있다. 

예루살렘 가면 큰 핍박이 있는데도 호랑이 굴로 가기 위해 서두르는 모양새다. 그럴 뿐만 아니라 사도바울은 얼마나 선교 과정에서 고난이 닥쳤는지 기록으로 쉽게 알 수 있다. 

그는 겸손함과 눈물로 인내하였다. 이 모는 것을 종합하면 바울은 기도의 사람이고 겸손 하며 열정의 사람인 것을 알 수 있다. 

그의 원동력은 말씀을 기초로 한 개인 기도인 듯하다. 

해안가에서 홀로 긴 시간을 기도하면서 주님과 무슨 대화를 하였을까? 

멋진 사명자들의 공통점은 모두 빠짐없이 기도의 사람인 것을 깨우친다.

 9. 적용:

산 기도를 자주 다니며 얻는 영적 유익이 많다. 오늘도 시간을 내어 주님과 깊은 대화와 받은 말씀을 묵상해야겠다.

10. 영적 터치 (단어 또는 구절)

13절: 걸어서 가고자 하여

11. 믿음과 회개 및 감사기도로 마무리', 0, true);
