8. 인간(해석):

- 삼년이나 동고동락했다면 이별하는 슬픔을 매우 클 것이다. 더욱이 리더로서 제자들을 양육했던 바울로썬 고난을 경험하게 될 제자들이 믿음에서 벗어날 것을 염려한 것으로 보인다. 

- 더욱이 삼년 동안 눈물로 제자들을 훈계했다는 바울의 말에 얼마나 열심히 사역했는지 상상할 수 있다. 

- 솔선수범하는 리더 바울은 범사에 모범을 보였다. 리더는 지시하는 자가 아니라 본을 보이는 자이다. 사역도 열심히하고 모든 일에 모범을 보인 바울의 리더십을 본 받아야겠다. 

9. 적용(나): 

- 바울의 리더십과 같이 낮은 자리에서 섬기는 마음이 내 안에 있길 소망한다. 

- 남북청년연합 선교회가 수고하고, 약한 자를 돕고, 받는 것보다 주는 것을 좋아하는 선교 단체가 되길 기도해야겠다.

10. 영적터치(단어/구절)

- 수고하고

