7. 하나님 찾기 (해석) 

8. 인간(해석):

- 인간의 탐욕의 끝은 어디일까? 예수님을 십자가에 못 박은 유대인들은 복음이 확장되어가고 있음에도 여전히 복음을 받아들이지 못했고, 예수를 믿는 제자들을 박해했다.

- 바울은 유대인들로부터 맞아 군사들에게 들려갈 정도임에도 불구하고, 천부장에게 요청하여 유대인에게 복음을 전한다.

- 죽음을 각오다곤 하지만 온 몸이 아픈 상황에서도 복음을 전한 바울을 생각하면 가슴이 먹먹해진다. 

- 우리는 복음을 전하기 유리한 환경에 있다. 물론 법적인 처벌을 받는 국가도 있다. 그러나 복음을 전할 때 욕은 해도 돌을 우리에게 던지지 않는다. 

- 바울보다 적어도 100배, 1000배, 10000배 이상 유리한 상황임에도 우리는 왜 전도를 하지 않는걸까? 

9. 적용(나): 

