 7. 하나님 찾기(해석)

주님은 자신을 박해하는 사울을 택하셨다. 

그리고 그를 복음의 일꾼으로 삼으셨다. 

주님은 사울을 세우실 때 왜 믿는 사람들 가운데 선별하지 않으셨을까? 

도리어 방해자를 복음 전파의 기둥으로 삼으셨을까? 

온전히 주님의 뜻을 헤아릴 수 없지만 주님은 핍박자여도 모든 영혼을 사랑하심이 분명하다. 

많은 사람은 과거 자신에게 상처를 준 사람이 있으면 현재도 그가 그런 사람일 것이라 단정 짓고 가까이 오는 것에 대하여 먼저 마음을 닫는다. 

어쩌면 이러한 모습이 약한 인간의 자연스러운 모습일지 모르겠다. 

나약한 인간을 하나님도 어느 정도 이해하실 것이다. 

하지만 오늘 본문에서 등장하는 주님은 적어도 그의 과거를 묻지 않으시고 복음의 증거 자로 세우셨다. 

지금 살고 있는 믿음 좋은 신앙인이라고 하더라도 분명 주를 영접하기 전에는 사탄의 누구나 사탄의 자녀였을 것은 분명하다. 

이러한 깨우침을 통해서 본다면 누구나 하나님의 십자가 사랑으로 하나님의 자녀가 될 수 있음이 확실시된다. 

그러므로 쉽지는 않지만 모든 사람을 사랑하며 그들에게 복음이 전해주기를 바라는 것이야말로 주님의 뜻임이 분명하다.

8. 인간 찾기(해석)

