6.인간 찾기(관찰)

- 베스도가 바울의 호소로 가이사에게 갈 때까지 바울을 지켜두라 명했음을 말함

- 베스도에게 나도 바울의 말을 들어보고 싶다 말하는 아그립바 왕

- 아그립바와 버니게가 의전을 받으며 접견 장소에 들어옴

- 베스도의 명으로 갇혀 있던 바울도 들어옴

- 베스도가 유대인들이 고소하여 바울 심문한 결과, 바울에게는 죄가 없었음

- 그러나 바울이 가이사에게 상소하였기에 가이사에게 보내기로 했다고 말함

- 또한 황제 앞에 보낼 때에 확실한 자료를 가지고 보내기 위해 이 자리를 마련했으며,

- 특히 아그립바 왕 앞에서 이 일을 행하는 것을 강조함 

