8.인간 찾기(해석)

- 베스도는 유대인들에게 인기를 끌기 위해 바울을 예루살렘으로 가서 심문하려고 했으나, 바울의 상소로 이곳에 있게 된 내용은 쏙 빼놓고, 바울의 호소로 이곳에서 지키고 있다고 말함

- 바울에게 복음에 대해 자세히 듣고 싶었던 아그립바 왕이 베스도에게 자기도 바울의 말을 듣고 싶다고 말함

- 아그립바 왕의 지위가 높기 때문에 베스도는 이것을 좋은 기회라고 생각했을 것임

- 베스도는 아그립바의 청을 수락하고 이튿날 접견 장소에 아그립바 왕을 모시고, 바울을 불러오게 함

- 이 자리에서 베스도는 유대인들의 고소로 바울을 심문했지만, 바울은 죄가 없었다라고 말함

- 베스도는 마치 바울의 상소가 아니었다면 바울은 죄가 없으니 풀어줬을 것처럼 말하고 있음

- 베스도는 바울을 황제 앞에 보내기 전에 확실한 자료를 얻고자 이 심문 자리를 마련했으며, 특별히 아그립바 왕 앞에서 심문한다는 것을 강조함

- 베스도는 아그립바 왕 앞에서 바울을 심문하는 것을 정치적 기회로 여기고 있고,

- 아그립바는 바울의 말을 듣는 것을 원하고 있다. 

9.적용(나) 

- 베스도는 자신의 정치적 야망을 달성하는데 바울을 이용하고 있지만, 정작 그는 바울을 로마로 안전하게 이동시키는 도구로 사용되고 있다.

- 바울은 가이사랴에 갇혀 있는 동안, 신변도 보장 받고, 로마의 주요 인사들에게 복음을 전하는 기회를 얻고 있음을 볼 수 있다.

- 세상 사람들이 어떤 꾀를 내어도 결국 선하신 하나님의 계획 안에서만 꾀를 낼 뿐임을 알 수 있다.

- 내가 어떤 상황 속에 있든지, 하나님은 내게 소망을 주시고, 그 소망을 이루어 가심을 기억하자

