부활 예수:15절 16절 17절 18절 

아그립바 왕: 13절 19절   

4. 주제 만들기:

아그립바 왕에게 간증하는 바울

5. 하나님 찾기 (관찰)

바울을 부르시는 부활 예수.

6. 인간 찾기(관찰)

아그립바 왕에게 신앙고백하는 바울.

7. 하나님 찾기(해석)

주님은 자신을 박해하는 사람조차도 고쳐 사용하신다. 크신 주님의 사랑을 생각할 때 감사만 나온다.

8. 인간 찾기(해석)

사도바울은 아그립바왕과 더불어 자신의 신앙고백을 하고 있다. 

자신 또한 한때는 지금 자신을 고발한 사람처럼 예수 믿는 사람들을 감금 및 핍박하는 데 앞장섰다. 

그 열정이 지나쳐 대제사장으로 멀리 있는 기독교인들을 합법으로 잡을 수 있는 위임장도 받았다. 

그러던 바울은 다메섹으로 가는 길 정오에 예수를 만났다. 

동시에 밝은 빛과 더불어 그의 눈이 어두워졌다. 

그는 예수의 음성을 듣는다. "사울아 사울아 네가 어찌하여 나를 박해하느냐 가시채를 뒷발질하기가 네게 고생이니라". 

내용의 의미를 쉽게 생각하면 하나님이 원하지 않는 대로 어리석게 살다가 고생만 한다는 내용이다. 

당시 농경문화였던 지역에 소를 키우는 것은 필수였을 것이다. 소 주인인 농부가 소를 끄는데 그 방향대로 가지 않고 가시채를 뒷발질하게 되면 분명 발 주변에 상처나 다칠 것이다. 

이 교훈은 누구에게나 적용될 수 있다고 생각한다. 지금 바울 앞에 있는 아그립바 왕을 포함하여 지금 시대에 살고 있는 신도들에게도 적용할 수 있다고 깨우침이 온다. 

자신 스스로는 교회나 가족을 위하여 하나님의 뜻이라고 믿고 움직였는데 그 반대일 수도 있다는 경우이다. 

그런 까닭에 주인이신 하나님의 음성을 듣는 것은 매우 중요하고 생각된다. 

그러므로 매일 정오 시간에 따로 중보기도 하는 시간은 정말 귀한 것 같다.

 

9. 적용(구체적으로)

3331 큐티를 통하여 더욱 주님의 방향(인도하심)을 들어야 하겠다. 더욱 귀를 기울이자!!

