도우심을 주시는 하나님

6. 인간 찾기(관찰)

변명하는 바울.

바울의 변명을 듣고 결박할 정도의 죄명을 찾지 못하는 베스도와 아그립바.

7. 하나님 찾기(해석)

바울이 유대 성전에서 죽을 수 있었는데 하나님의 도우심으로 바울은 살 수 있었다. 

사명자는 일이 끝나기 전까지는 결코 죽거나 쓰러질 수 없다. 

왜냐하면 생명의 주관자이신 하나님이 지켜주시기 때문이다.

8. 인간 찾기(해석)

결박당한 바울은 자신을 심문하는 아그립바왕과 총독 베스도에게 담대하게 복음을 전파했다. 

복음을 듣고 있던 그들은 그 진리를 받아들이지는 않았지만 그렇다고 바울이 결박당할 만한 행위를 한 것도 찾지 못했다. 

도리어 석방시키고자 하는 마음도 있었다. 

그러면 누가 바울을 결박시켰을까? 

바울 스스로가 결박당한 것일까? 답은 29절에 나와 있다. 왕과 총독 포함하여 누구나 복음을 듣고 받아들인 사람은 바울처럼 전파자가 되는 것을 하나님이 원하신다는 것이다. 

다만 바울이 결박당한 것은 모든 사람에게 포함한 하나님이 원하시는 것은 아님을 나타낸다. 

그러면 바울이 결박당한 것은 특별한 하나님의 뜻이고 그에 순종하는 바울의 믿음을 발견한다. 

어쩌면 바울을 옴짝달싹 못 하게 하는 밧줄이 아니라 로마까지 안전하게 지켜주는 안전띠 같은 것이다. 

이 부분을 우리의 인생에 놓고 비춰본다면 신앙인들에게 나타나는 여러 가지 어려움과 시험이 도리어 주님을 의지하게 만들어 주님이 원하시는 목적지까지 갈 수 있도록 돕는 역할을 할 수도 있겠다고 생각해보았다. 

 

