8. 인간(해석):

- 바울은 예수 그리스도의 종, 사도로 부름 받은 사람으로 자신의 정체성을 로마에 있는 성도들에게 드러냈다.

- 로마를 방문한 적이 없고, 자신이 세운 교회가 아니었기 때문에 편지를 보내는 것은 쉽지 않은 일이었을 것 같다.

- 그러나 로마에는 유대인과 이방인이 함께 신앙 생활을 하며 생긴 갈등이 존재했고, 바울이 로마를 복음의 주요 거점지로 생각했기 때문에 복음을 체계적이고 신학적으로 안내하려는 의도가 있었을 것이다.

- 로마 교회를 생각하면 현재 분단되어 있는 남과 북을 생각하게 된다. 

- 현재 남과 북은 너무도 다른 모습으로 살고 있다. 통일이 된다면 서로가 바라는 삶을 다를 것이다. 

- 그럴 때 필요한 것은 복음이다. 복음은 우리를 하나로 연결할 수 있고, 복음을 바탕으로 한 삶의 모습을 서로가 다른 점을 이해하고 보완할 수 있을 것이다. 

- 우리의 삶의 현장도 마찬가지이다. 복음을 중심으로 한 삶의 태도는 나와 생각이 다르다고 배척하는 것이 아니라 그것을 이해하고, 수용하고 포용하게 된다.

- 복음이 우리 안에 잘 심어지길 소망한다.

