1:감동받는 단어나 구절 찾기(영적터치)

1. 1분기도

2. 본문성경 읽기(3번)

3. 반복단어 찾기(형광펜 추천)

4. 주제만들기: 교회를 다니는 성도들이 흔히 하는 착각

5. 하나님 찾기 (관찰)

- 외모로 사람을 취하지 않으시고, 율법의 유무에 따라 공정하게 심판하시는 하나님

- 율법을 행하는 자를 의롭다 하시고 사람의 은밀한 것도 심판하시는 하나님

- 예수 그리스도로 말미암아 심판하시는 하나님

6. 인간 찾기 (관찰)

- 어떤 사람은 율법 없이 범죄하고, 어떤 이는 율법 안에서 범죄한다고 말하는 바울

- 율법 없는 이방인도 양심으로 율법을 행할 수 있다고 말하는 바울

- 사람의 양심과 생각은 서로 고발하거나 변명한다고 말하는 바울

- 유대인은 율법을 의지하고, 하나님을 자랑한다고 말하는 바울

- 스스로 교사와 선생이라 믿으며, 다른 이들을 인도한다고 생각한다고 말하는 바울

7. 하나님 찾기 (해석) 

- 세상 사람들은 사람의 외모, 즉 그 사람이 가진 스펙으로 사람을 평가하지만 하나님은 세상의 기준과는 다른 공평한 기준을 갖고 계시다.

- 그것은 하나님을 믿는 믿음과 행위, 스스로 의롭다 여김을 받을 수 없는 죄인임을 인정하는 겸손함 등일 것이다.

- 얼마나 감사한 일인가? 나는 스스로 의로울 수 없는 존재이기에 하나님을 의지하며 살아가기만 하면 된다. 

8. 인간(해석):

- 이런 착각을 자주 한다. 

- 매주 예배를 드리고, 교회에서 하는 봉사도 잘 참여하며, 성경도 읽고, 기도도 잘하기 있기 때문에 스스로 의롭다고 착각한다.

- 얼마나 무서운 일인가?! 스스로 의롭다고 여기며, 기준에 못 미치는 사람을 정죄하고, 무시하고, 깔보는 마음이 우리 안에 가득하다.

- 우리라기 보다는 내 안에 가득하다. 완악한 마음과 교만한 마음이 내 안에 사라지길 간절히 소망한다.

- 오직 우리는 예수 그리스도로 말미암아야 의롭다함을 겨우 인정 받을 수 있는 존재이다.

9. 적용(나): 

- 행위로 의롭다 함을 인정 받으려 하지 말고, 말씀을 의지하며 예수님의 발자취를 따라갈 수 있도록 은혜를 주시도록 기도해야겠다.

10. 영적터치(단어/구절)

- 스스로 믿으니

11. 믿음과 회개 및 감사기도로 마무리

12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);
INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-03-13', '로마서', '2장 21~29절', '진정한 할례 자는 누구인가?', '(로마서 2장)

21. 그러면 다른 사람을 가르치는 네가 네 자신은 가르치지 아니하느냐 도둑질하지 말라 선포하는 네가 도둑질하느냐

22. 간음하지 말라 말하는 네가 간음하느냐 우상을 가증히 여기는 네가 신전 물건을 도둑질하느냐

23. 율법을 자랑하는 네가 율법을 범함으로 하나님을 욕되게 하느냐

24. 기록된 바와 같이 하나님의 이름이 너희 때문에 이방인 중에서 모독을 받는도다

25. 네가 율법을 행하면 할례가 유익하나 만일 율법을 범하면 네 할례는 무할례가 되느니라

26. 그런즉 무할례자가 율법의 규례를 지키면 그 무할례를 할례와 같이 여길 것이 아니냐

27. 또한 본래 무할례자가 율법을 온전히 지키면 율법 조문과 할례를 가지고 율법을 범하는 너를 정죄하지 아니하겠느냐

28. 무릇 표면적 유대인이 유대인이 아니요 표면적 육신의 할례가 할례가 아니니라

29. 오직 이면적 유대인이 유대인이며 할례는 마음에 할지니 영에 있고 율법 조문에 있지 아니한 것이라 그 칭찬이 사람에게서가 아니요 다만 하나님에게서니라

