참되심: 4절 7절

4. 주제 만들기:

참되신 하나님과 불의한 인간

5. 하나님 찾기 (관찰)

참되신 하나님

미쁘신 하나님

심판자가 되신 하나님 

6. 인간 찾기(관찰)

참되신 하나님과 죄인인 인간에 대하여 설명하는 바울.

7. 하나님 찾기(해석)

하나님은 의를 부각하기 위하여 불의를 기뻐하지 않으신다. 

도리어 하나님은 미쁘시어 모든 죄인이 참복음을 믿고 의의 길로 돌아오기를 원하신다.

8. 인간 찾기(해석)

바울은 10절에 확실하게 인간에 대하여 말한다. 

"의인은 없나니 하나도 없으며." 이 내용을 묵상하면 주님의 복음이 인간들에게 얼마나 소중한가를 더욱 느끼게 된다. 

이렇게 바울이 설명하면 다른 유대인들은 이렇게 반문할 것이다. 

만약 모든 인간이 죄인이라면 선택받은 이스라엘 백성의 유익은 무엇인가? 

할례는 왜 하는가? 이에 대하여 바울은 이스라엘 백성에게 먼저 말씀을 맡겨주셨다고 말하였다. 

즉 복음을 받을 기회의 특권을 주셨다는 것이다. 그 혜택을 받은 유대인 중에는 말씀을 믿지 않은 자들도 있었다. 

믿음이 당장 없다고 하여 하나님은 그들을 쉽게 포기하지 않는다. 왜냐하면 하나님은 죄를 덮고 용서하실 정도로 미쁘심을 지닌 분 이 시기 때문이다. 

그렇다고 의도적으로 악을 행함으로 의를 부각하는 것도 바울은 차단했다. 

결국 믿는다는 것은 먼저 자신이 죄인인 것을 인정하고 겸손한 태도로 말씀을 받아들이고 감사하는 마음을 가짐으로 오직 주를 찾는 것을 간절히 주님이 원하신다는 것이다.

9. 삶의 적용(구체적으로)

미쁘시고 자비로우신 하나님을 기억하며 오늘도 하나님께 감사의 묵상 시간을 가져야겠다.

10. 영적 터치 (단어 또는 구절)

10절: 기록된바 의인은 없나니 하나도 없으며

11. 믿음과 회개 및 감사기도로 마무리', 0, true);
INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-03-16', '로마서', '3장 21~31절', '하나님의 의', '로마서 3장

21   이제는 율법 외에 하나님의 한 의가 나타났으니 율법과 선지자들에게 증거를 받은 것이라

22   곧 예수 그리스도를 믿음으로 말미암아 모든 믿는 자에게 미치는 하나님의 의니 차별이 없느니라

23   모든 사람이 죄를 범하였으매 하나님의 영광에 이르지 못하더니

24   그리스도 예수 안에 있는 속량으로 말미암아 하나님의 은혜로 값 없이 의롭다 하심을 얻은 자 되었느니라

25   이 예수를 하나님이 그의 피로써 믿음으로 말미암는 화목제물로 세우셨으니 이는 하나님께서 길이 참으시는 중에 전에 지은 죄를 간과하심으로 자기의 의로우심을 나타내려 하심이니

26   곧 이 때에 자기의 의로우심을 나타내사 자기도 의로우시며 또한 예수 믿는 자를 의롭다 하려 하심이라

27   그런즉 자랑할 데가 어디냐 있을 수가 없느니라 무슨 법으로냐 행위로냐 아니라 오직 믿음의 법으로니라

28   그러므로 사람이 의롭다 하심을 얻는 것은 율법의 행위에 있지 않고 믿음으로 되는 줄 우리가 인정하노라

29   하나님은 다만 유대인의 하나님이시냐 또한 이방인의 하나님은 아니시냐 진실로 이방인의 하나님도 되시느니라

30   할례자도 믿음으로 말미암아 또한 무할례자도 믿음으로 말미암아 의롭다 하실 하나님은 한 분이시니라

31   그런즉 우리가 믿음으로 말미암아 율법을 파기하느냐 그럴 수 없느니라 도리어 율법을 굳게 세우느니라

