6. 인간 찾기(관찰)

원죄를 저지른 아담

죄에 빠져 죽게 된 모든 인간

주 예수 그리스도로 말미암아 다시 구원받게 된 인간

7. 하나님 찾기(해석)

하나님의 첫 번째 인간 아담은 선악과를 따먹는 원죄를 저질렀다. 

이후로는 모든 인간은 이 땅에서 영원히 머무르지 못하게 되었다. 

아담에서 모세 때까지 죄를 짓지 않은 사람이더라도 사망이라는 저주에 걸렸다. 

이러한 어둠의 고리를 풀기 위해 은혜의 하나님은 자신의 독생자 예수 그리스도를 죽이시는 방법을 선택하셨다. 

죄인이 된 인간을 구하시려 거룩한 아들을 희생시킨 것이다. 

이성적으로는 상상할 수 없는 하나님만 하실 수 있는 크신 사랑이다. 

이러한 부분을 생각할 때 매일의 삶 가운데 주님께 감사하며 살지 못할 이유가 없다.

