7.하나님 찾기(해석)

8.인간 찾기(해석)

- 신자는 죄에 대해서 죽은 자가 되어 죄를 짓지 말라고 한다.

- 우리가 은혜로 구원을 받았으므로 법 아래에 있지 아니하나,

- 죄를 지으면 죄에게 순종한 것이니 죄의 종이 되는 것이라고 논리적으로 설명한다.

- 우리 몸을 하나님께 드리되, 죽었다가 다시 살아난 자처럼 하나님께 드리라고 한다.

- 죽었다가 하나님의 은혜로 살아나는 기적을 체험한 자 또는 하나님을 위해 다시 태어난 사람처럼 자신의 삶을 하나님께 온전히 바치라는 것이다.

- 하나님을 체험하는 수많은 방법 중에 죽었다가 살아나는 기적처럼 극적인 것은 없을 것이다.

- 가장 큰 감동과 기쁨으로 하나님을 위해 목숨을 바치라는 것이다.

- 그런데 그 목숨을 바치는 행동이 바로 순종이다. 

- 죄에 대하여는 죽은 자, 하나님께 순종하는 자가 되라는 것이다.

- 바울은 죄와의 싸움을 매우 중요하게 생각했고, 우리 신자들에게 그 중요성을 말하고 있다.

- 우리는 하나님의 종이 되어 거룩함에 이르는 열매를 맺었는데 그 마지막은 영생이다.

- 죄의 삯은 사망이고, 하나님의 선물은 그리스도 예수 우리 주 안에 있는 영생이다.

- 신자는 하나님께서 주신 은혜의 선물을 감사히 받고 잘 간직해야 한다.

- 오직 그리스도 예수 우리 주 안에서.

9.적용(나) 

- 성령을 처음 받았을 때 죄를 짓지 않는 것이 자연스러웠다.

- 죄는 역겨운 것이었고, 죄의 유혹을 물리치는 것이 자연스러웠다.

- 그러나 성령의 불이 사그라든 지금 나는 생각으로도 말로도 죄를 수없이 저지르고 있다.

- 시작은 생각부터였다.

- 그때 악한 생각을 끊어내려고 목숨을 걸었어야 했는데, 그렇게 하지 못했다.

- 그러다 보니 운전하다가 혼잣말로 남을 저주하는 지경까지 와버렸다.

- 나에게 무례히 행하는 자를 미워하는 지경까지 와버렸다.

- 죄와 싸우되 목숨을 걸고 싸워야 한다. 

- 나는 하나님의 거룩한 자녀이고, 의의 무기라는 것을 기억해야 한다.

- 오직 그리스도 예수 나의 주 안에서.

