법/율법: 1절 2절 3절 4절 5절 6절 7절 8절 9절

법에서 자유롭게 되나니/법에서 벗어나느니라/율법에서 벗어났으니: 2절 3절 6절

알지 못하였으니/ 알지 못하였으리라: 7절  

살아나고/살았더니/생명: 9절 10절

4. 주제 만들기:

새롭게 살리는 열매

5. 하나님 찾기 (관찰)

율법을 통하여 죄를 일깨워 주시는 하나님

죄인 된 인간을 다시 살리시는 하나님.

6. 인간 찾기(관찰)

율법으로 인하여 죄에 갇힌 인간들.

7. 하나님 찾기(해석)

하나님은 자신의 사랑하는 독생자 예수를 죽이셨다. 

죽인 이유는 피조물인 인간을 너무 사랑하사 온전한 자유를 주시기 위함이다. 

원래 율법을 인간에게 허락하신 이유는 율법을 통하여 인간에게 죄를 짓지 말기 위함이었다. 

그런데 인간은 죄를 지속해 범할 뿐만 아니라 그 율법을 가지고 인간 스스로 교만하여 다른 사람들을 정죄하는 도구로 사용하였다. 

이러한 모든 것을 아신 하나님은 율법으로 인하여 죽을 수밖에 없는 인간을 위하여 대신하여 죽음의 죗값을 예수께 받게 하셨다. 

우리를 온전케 하시고자 그분은 스스로 큰 수모와 고통을 감내하셨다. 

이러한 부분을 생각할 때 내가 지금 누리고 있는 영적 자유로움은 예수님의 보혈과 맞바꾼 그것으로 생각한다. 

늘 감사함으로 사는 것이 신자의 도리인 것은 확실하다.

8. 인간 찾기(해석)

9. 삶의 적용(구체적으로)

오늘은 크리스마스이브이다. 인간에게는 축제의 날이지만 하나님 편에서는 사랑하는 아들과 헤어지는 전날이기도 하다. 

기쁨의 날을 맞이하면서도 더욱 감사하는 마음 가져야겠다. 

잠시 시간을 내어 크리스마스의 깊은 의미를 생각하는 시간을 가져야겠다.

10. 영적 터치 (단어 또는 구절)

6절: 우리가 영의 새로운 것으로 섬길 것이요

11. 믿음과 회개 및 감사기도로 마무리', 0, true);
INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-03-25', '로마서', '7장 11~20절', '인간은 죄로 인해 선을 행할 능력이 없음', '로마서 7장

11   죄가 기회를 타서 계명으로 말미암아 나를 속이고 그것으로 나를 죽였는지라

12   이로 보건대 율법은 거룩하고 계명도 거룩하고 의로우며 선하도다

13   그런즉 선한 것이 내게 사망이 되었느냐 그럴 수 없느니라 오직 죄가 죄로 드러나기 위하여 선한 그것으로 말미암아 나를 죽게 만들었으니 이는 계명으로 말미암아 죄로 심히 죄 되게 하려 함이라

14   우리가 율법은 신령한 줄 알거니와 나는 육신에 속하여 죄 아래에 팔렸도다

15   내가 행하는 것을 내가 알지 못하노니 곧 내가 원하는 것은 행하지 아니하고 도리어 미워하는 것을 행함이라

16   만일 내가 원하지 아니하는 그것을 행하면 내가 이로써 율법이 선한 것을 시인하노니

17   이제는 그것을 행하는 자가 내가 아니요 내 속에 거하는 죄니라

18   내 속 곧 내 육신에 선한 것이 거하지 아니하는 줄을 아노니 원함은 내게 있으나 선을 행하는 것은 없노라

19   내가 원하는 바 선은 행하지 아니하고 도리어 원하지 아니하는 바 악을 행하는도다

20   만일 내가 원하지 아니하는 그것을 하면 이를 행하는 자는 내가 아니요 내 속에 거하는 죄니라

