6.인간 찾기(관찰)

- 죄가 계명으로 말미암아 자신을 속이고 죽였다고 말하는 바울

- 바울은 율법과 계명은 거룩하고 의로우며 선한 것이기 때문에 그것을 지켜야 한다는 것을 알지만, 자신 속에 있는 죄로 인해 죄를 범하고 있음을 말함

- 율법과 계명으로 인해 죄를 알게 되고 죄가 심각하게 악한 것임을 깨닫게 되는 것

- 바울은 선을 행하길 원하지만 선을 행하지 않고 도리어 악을 행하고 있는 것을 발견함

- 악을 행하는 것은 자신이 아니라 자기 속에 거하는 죄라는 것을 깨달음

7.하나님 찾기(해석)

8.인간 찾기(해석)

- 바울은 율법과 계명의 거룩함, 선함, 의로움에 대해 정확히 말한다.

- 자신은 이것을 확신하고 믿으며 이것을 지키고자 하지만, 이것을 통해 자신의 죄를 깨닫게 될 뿐임을 알게 되었다.

- 죄와 피흘리기까지 싸우지만, 승리할 수 없고 도리어 자신이 패배하는 것을 깨달으며, 자신의 능력으로는 죄와의 싸움에서 패배할 수 밖에 없음을 꺠달음

- 바울은 자신의 의지와 다르게 악을 행하게 되는 것을 고백함으로 인간의 원죄와 죄성, 타락에 대해 말하고 있다

- 우리 신자는 구원받고 성령님의 능력으로 살아가지만, 성령님께서 주장하시는 대로 살지 못할 때가 많다.

- 그것은 원죄로 인해 타락한 인간의 본성 때문인데, 신자들은 이렇게 죄와 싸우며 하나님 나라를 살아가야 한다(성화의 삶).

- 바울은 이것을 정확히 꿰뚫어 알뿐만 아니라, 기록하여 독자들 또한 깨닫길 바라면서 로마서를 작성한 것으로 보인다.

9.적용(나) 

- 성령으로 충만하지 않으면, 죄와의 싸움에서 질 뿐이다. 

- 정확히 말해 나는 성령님의 도움 없이는 죄와의 싸움에서 패배할 수 밖에 없는 존재이다.

- 구원도 성화의 삶도 하나님의 은혜 없이는 할 수 없는 존재라는 것을 기억하고 늘 주님을 의지하고 감사하며 살아야 한다. 

