4. 주제만들기: 그릇을 만드신 하나님

5. 하나님 찾기 (관찰)

- 귀히 쓸 그릇과 천히 쓸 그릇을 만들 권한이 있으신 하나님

6. 인간 찾기 (관찰)

- 호세아와 이사야 선지자의 예언을 증언하는 바울

7. 하나님 찾기 (해석) 

- 세상에 악이 만연하고, 믿지 않는 사람들이 많지만 모든 것은 하나님의 주권과 섭리 안에 있다.

- 하나님은 우리를 어떻게 사용하실지 그 분의 의지와 선택에 따라 우리를 사용하신다.

- 그렇다고 해서 믿지 않은 자들은 하나님의 선택에서 벗어났다고 볼 순 없다. 우리를 통해서 하나님의 영광이 드러나도록 하기 위함일지, 알 수는 없지만 하나님은 모든 인간을 동일하게, 동등하게 사랑하신다.

- 그렇다면 우리는 이런 현상에 의문을 제기할 것인가? 아니면 은혜에 감사하고, 믿지 않는 자들이 하나님을 믿도록 노력할 것인가를 선택해야 한다. 

- 전자와 같이 해석되지 않는 문제에 사로잡히는 어리석음보단 내가 받은 은혜를 빨리 전하는 것이 나을 것이다.

- 하나님은 우리 모두를 사랑하신다.

8. 인간(해석):

- 우리에게 주어진 복음은 은혜이다. 은혜라는 단어로 감사할 일이 너무도 많다. 

- 그런데 복음으로 은혜를 받은 내가 행위로 정죄하는 유대인이 되어버렸다. 

- 십자가 앞에서 눈물 흘리고 감격하던 은혜는 식고, 행위로 판단하고, 기준을 세우는 사람이 되어버렸다.

- 복음의 본질은 사랑이다. 값없이 주어진 십자가의 은혜로 돌아가 사랑을 깨닫고 전하는 사람이 되어야 한다.

9. 적용(나): 

- 은혜를 받았음에도 유대인과 같이 변해버린 모습에 회개한다. 

- 은혜에 감사하며 하나님의 사랑을 전하는 2026년이 되길 소망한다.

