6.인간 찾기(관찰)

- 이스라엘이 넘어짐으로 구원이 이방인에게 이르게 됨

- 바울은 이방인의 사도라는 직분을 영광스럽게 여김

- 버림받은 이스라엘을 다시 받아들이는 것은 죽은 자가 살아는 것과 같음

- 접붙임 받은 가지가 떨어진 가지를 향하여 자랑하지 말아야 함

- 접붙임 받은 가지는 뿌리가 보전해 주는 것이다

- 이방인은 마음을 높이지 말고 도리어 두려워하라

7.하나님 찾기(해석)

8.인간 찾기(해석)

- 이스라엘이 복음을 거부함으로 이방인에게 복음이 신속하고 넓게 전파됨

- 이방인이 구원을 받음으로 이스라엘이 시기하게 되고 이로 말미암아 이스라엘도 구원받게 되기를 원함

- 여기서 이스라엘의 시기는 구원에 이르는 시기가 된다.

- 여기에는 하나님의 놀라운 계획과 섭리가 있을 것이다.

- 바울은 이방인의 사도라는 직분을 영광스럽게 여긴다.

- 버림받은 이스라엘이 구원받는 것은 부활의 의미를 지니는 것

- 접붙임 받은 가지인 이방인은 떨어진 가지인 이스라엘을 향하여 자랑하면 안 된다.

- 뿌리가 가지를 보전하고 가지가 뿌리를 보전하지 않듯이 뿌리가 먼저다.

- 믿음의 뿌리는 아브라함 등 믿음의 조상이다.

- 믿음으로 구원을 받은 것이므로 신자는 두려워하고 겸손해야 한다.

9.적용(나) 

- 복음을 거부하는 이스라엘 사람들을 보면서 답답할 때가 많았는데,

- 답답하다고 느낀 것은 그들을 무시하는 내 안의 교만이었음을 깨닫게 되었다.

- 이제는 이스라엘 사람들을 무시하는 것이 아니라 그들을 위하여 기도해야겠다.

