6. 인간 찾기 (관찰)

- 너희 몸을 하나님이 기뻐하시는 거룩한 산 제물로 드리라는 바울

- 거룩한 산 제물은 영적 예배임을 알려주는 바울

- 이 세대를 본 받지 말고 마음을 새롭게 하여 하나님의 뜻을 분별하라 말하는 바울

- 마땅히 생각할 그 이상을 생각하지 말고 하나님께서 나누어 주신 믿음의 분량대로 지혜롭게 생각하라는 바울

