8. 인간 찾기(해석)

바울은 우리를 박해하는 자를 저주하지 말고 오히려 축복하며, 원수를 원수로 갚지 말고 도리어 

그들의 필요를 채워 주라고 권고한다. 이성적으로 생각해 보면 결코 쉬운 일이 아니다. 조금 양보해서, 자신을 핍박한 사람을 최대한 배려하는 수준이 그저 피하는 정도일 것이다.

그런데 왜 바울은 주님의 심정으로 원수를 사랑하는 단계까지의 영적 성장을 요구하는 것일까? 

아마도 하나님의 사랑이야말로 가장 강력한 능력임을 가르쳐 주려는 목적이 아닐까 생각한다. 

사실 우리 신자들 역시 과거에는 하나님을 대적했던 마귀의 자녀, 곧 원수였다. 그러나 하나님의 십자가 사랑으로 말미암아 하나님의 자녀로 다시 태어났다. 이처럼 하나님께서는 원수를 사랑하시는 것이 자연스러운 분이시다.

마찬가지로 하나님의 자녀 된 우리도 아버지를 닮아 불신자들을 사랑으로 축복하고, 사랑의 복음을 전한다면 그들 또한 크신 하나님의 자녀가 되는 같은 특권을 누리게 될 것이다. 

즉 사랑은 갇혀 있는 것이 아니라 생명력이 있어 물처럼 끊임없이 흘러가는 특징을 지닌다. 결국 사람은 어떠한 악에게도 절대로 패배하지 않는다.

