- 사람마다 어떤 날을 더 낫게 여기는 사람이 있고, 어떤 사람은 매일을 같게 여기는 사람이 있다고 말하는 바울

- 살아도 주를 위해 살고, 죽어도 주를 위해 죽으니, 사나 죽으나 주의 것이라 말하는 바울

