7. 하나님 찾기 (해석) 

- 하나님은 우리 모두를 동등하게 사랑하신다.

- 인간인 우리는 서로 사랑하는 것이 불가능에 가깝지만 하나님은 우리 모두에게 동일한 사랑을 주신다. 얼마나 감사한 일인가?

- 나의 어떠한 모습이라도 하나님은 나를 사랑하신다.

8. 인간(해석):

- 바울은 믿음이 연약한 자를 비판하지 말라고 했다. 당시 상황에서 연약한 믿음은 다양한 형태였을 것이다. 

- 나라면 과연 어떻게 했을까? 복음을 전하며 목숨을 잃을 수 있는 위기에 직면해 있는 상황에서 믿음이 연약한 사람을 챙길 수 있는 마음이 내 안에 있을 수 있을까?

- 그럼에도 바울은 믿음이 연약한 자를 비판하지 말라고 했다. 하나님은 그 사람도 동일하게 사랑하기 때문이다.

- 어쩌면 믿음이 없다고 생각하며 불안해하고 예민하게 생각하는 나의 믿음이 더 연약한 믿음일 수도 있다는 생각이 든다. 

- 살아도 주를 위해 살고, 죽어도 주를 위해 죽는 믿음이 내 안에 생기길 소망한다.

9. 적용(나): 

