5.하나님 찾기(관찰)

- 예수님께서 내가 살았노니 모든 무릎이 내게 꿇을 것이요 모든 혀가 하나님께 자백하리라 말씀하심

6.인간 찾기(관찰)

- 우리 각 사람이 자기 일을 하나님께 직고할 것임

- 다시는 서로 비판하지 말고 부딪치거나 거칠 것을 형제 앞에 두지 말아야 함

- 하나님의 나라는 먹는 것과 마시는 것이 아니요 오직 성령 안에 있는 의와 평강과 희락이다

- 그리스도를 섬기는 자는 하나님을 기쁘시게 하며 사람에게도 칭찬을 받음

- 형제를 거리끼게 하지 말아야 함

7.하나님 찾기(해석)

- 심판 날에 모든 사람은 예수님 앞에 무릎을 꿇고 자신의 행위를 하나님께 자백할 것이다

8.인간 찾기(해석)

- 신자는 서로 비판하지 말고 형제들 앞에서 바른 행동을 해야 한다.

- 하나님의 나라는 먹고 마시는 기쁨에 있는 것이 아니라 오직 성령 안에 있는 의와 평강과 희락이다

- 먹는 것과 마시는 것에 집중하기 보다 예수님을 섬기고 성령님께 집중해야 한다

- 고기와 포도주를 먹지 아니하고 무슨 일이든지 형제를 거리끼게 하지 않아야 한다

- 로마시대에는 고기와 포도주의 대부분이 우상 숭배에 사용된 것들이었다

- 고기와 포도주는 모두 하나님이 만드신 것이기에 그 믿음이 확실하다면 머고 마시는 것에 자유해도 되지만, 이것을 먹고 마심으로 실족하게 될 또 다른 신자를 위해 먹지 않는 것이 아름다운 것이다

9.적용(나) 

- 늘 믿음 안에서 말하고 행동하며, 형제들 앞에서 겸손하게 행동해야 한다.

- 나는 신자를 판단하는 판관이 아니라, 예수님을 섬기는 종이어야 한다.

- 미각의 즐거움과 육체적 만족감을 추구하기보다는 예수님을 섬기는 것과 성령 안에 있는 의와 평강과 희락을 누리도록 노력해야겠다.

