INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-04-15', '로마서', '15장 1~10절', '하나님의 영광', '(로마서 15장)

1.  믿음이 강한 우리는 마땅히 믿음이 약한 자의 약점을 담당하고 자기를 기쁘게 하지 아니할 것이라

2. 우리 각 사람이 이웃을 기쁘게 하되 선을 이루고 덕을 세우도록 할지니라

3. 그리스도께서도 자기를 기쁘게 하지 아니하셨나니 기록된 바 주를 비방하는 자들의 비방이 내게 미쳤나이다 함과 같으니라

4. 무엇이든지 전에 기록된 바는 우리의 교훈을 위하여 기록된 것이니 우리로 하여금 인내로 또는 성경의 위로로 소망을 가지게 함이니라

5. 이제 인내와 위로의 하나님이 너희로 그리스도 예수를 본받아 서로 뜻이 같게 하여 주사

6. 한마음과 한 입으로 하나님 곧 우리 주 예수 그리스도의 아버지께 영광을 돌리게 하려 하노라

7. 그러므로 그리스도께서 우리를 받아 하나님께 영광을 돌리심과 같이 너희도 서로 받으라

8. 내가 말하노니 그리스도께서 하나님의 진실하심을 위하여 할례의 추종자가 되셨으니 이는 조상들에게 주신 약속들을 견고하게 하시고

9. 이방인들도 그 긍휼하심으로 말미암아 하나님께 영광을 돌리게 하려 하심이라 기록된 바 그러므로 내가 열방 중에서 주께 감사하고 주의 이름을 찬송하리로다 함과 같으니라

10. 또 이르되 열방들아 주의 백성과 함께 즐거워하라 하였으며

