신자의 본분은 하나님의 영광을 위하여 사는 것이다. 쉽지 않은 삶을 인내하며 소망을 품을 수 있는 이유는 하나님의 절대적인 위로가 있기 때문이다.

신자는 믿음이 약한 자를 비방하는 것이 아니라, 도리어 그 약함을 도와주고 그로 인한 열매를 자랑하지 않는 것이 하나님께 영광을 올려 드리는 올바른 태도일 것이다. 

결국 모든 신자는 하나의 목표, 곧 하나님의 영광을 위하여 살기 위해 각자의 자리에서 최선을 다하고 있으며, 비록 현재의 믿음이 더 크거나 부족해 보일지라도 모두 동일하게 주님께서 원하시는 방향을 향해 살아가야 될 것이다.

자녀들은 스스로 할 수 없지만, 먼저 모범을 보여 주신 주 예수 그리스도를 묵상하며 그분을 따라가면 될 것이다. 

아무리 자신이 믿음이 높다고 생각하고 주변 사람들에게 칭찬받는다 하더라도, 믿음이 약한 자를 경멸한다면 가장 먼저 회개해야 할 대상이 바로 자신일 것이다.

아무리 큰 열정이 있다 하더라도 겸손이 없다면, 그 열정은 결코 열매를 맺지 못할 것이다.

