4.주제 만들기: 복음의 제사장 직분

5.하나님 찾기(관찰)

- 바울을 하나님의 복음의 제사장 직분을 하게 하심

6.인간 찾기(관찰)

- 바울은 은혜로 이방인을 위하여 하나님의 복음의 제사장 직분을 갖게 됨

- 이 은혜로 말미암아 이방인이 성령 안에서 거룩하게 되고 제물로 드려지도록 하신 것

- 그리스도께서 역사하신 것 외에는 바울이 감히 말하지 않음

- 예루살렘으로부터 두루 행하여 일루리곤까지 그리스도의 복음을 편만하게 전함

- 그리스도의 이름을 부르는 곳에서는 복음을 전하지 않으려고 노력함

7.하나님 찾기(해석)

- 하나님은 은혜로 이방인을 구원하시고자 바울에게 복음의 제사장 직분을 주셨다

8.인간 찾기(해석)

- 바울은 하나님의 은혜로 말미안아 하나님의 복음의 제사장 직분을 받았으며, 이 직분을 감당하기 위해 자기 목숨도 아깝게 여기지 않았다.

- 바울을 통하여 이방인이 성령 안에서 거룩한 산 제물이 되는 놀라운 역사가 일어나는 것이다.

- 이것을 깨달아 알았기에 바울은 자신의 직분을 그리스도 예수 안에서 자랑스럽게 여겼다.

- 그러나 이것을 자신의 능력으로 여기지 않고 오직 그리스도께서 자신을 통하여 역사하셨음을 말하였다.

- 이방인에게 복음이 전해진 것은 성령의 능력으로 이루어졌으며 예루살렘부터 두루 다니며 일루리곤까지 복음을 편만하게 전파했다.

- 바울은 목숨을 걸고 복음을 전하면서도 이미 그리스도의 이름이 불려지는 곳에서는 복음을 전하지 않고, 그리스도의 이름을 모르는 곳에서 열심히 복음을 전하였다.

- 이것은 얼마나 큰 겸손이요, 다른 전도자에 대한 배려인가. 

- 또한 이런 행동으로 복음이 넓게 퍼지는데 효율성을 더하였을 것이다.

9.적용(나) 

- 확신에 찬 것을 말하지 않고 참는 것은 쉽지 않은 것이며,

- 아무도 예수님을 모르는 곳에서 복음을 전하며 개척하는 일은 매우 어려운 일이다.

- 바울은 복음 앞에서 겸손하고 다른 전도자들을 배려할 줄 아는 자였지만, 개척지에서는 저돌적이었다.

- 이런 바울의 모습을 닮도록 노력해야겠다.

 

