4. 주제 만들기:

악함으로부터 떠나라

5. 하나님 찾기 (관찰) 

평강의 하나님

은혜의 예수

6. 인간 찾기 (관찰)

동역자를 맞이하라고 부탁하는 바울

악한 자들을 경계하고 멀리할 것을 당부하는 바울

7. 하나님 찾기(해석)

8. 인간 찾기(해석)

바울은 동역자들뿐 아니라 그들의 가족과 어머니에 이르기까지 섬세하게 돌보는 모습을 보여 준다. 이를 통해 그가 예수님의 사랑을 얼마나 깊이 마음에 품고 있었는지를 알 수 있다. 

과거 청년 시절의 바울은 이미지가 매우 강하고 거침없는 인물이었으나, 이제는 누구나 다가가고 싶어 할 만큼 따뜻한 사람으로 변화되었음을 볼 수 있다.

그러나 그렇다고 해서 교회 공동체 안에서 무조건 모든 것을 수용하라고 가르치지는 않는다. 

바울은 순진한 사람들의 마음을 미혹하는, 거룩하지 않고 교활한 마음을 가진 자들을 경계해야 하며, 경우에 따라서는 떠나게 하라고까지 말한다. 사탄은 어떤 모습으로든 하나님의 자녀들을 힘들게 하고 시험에 들게 하기에, 특별한 지혜가 필요하다고 바울은 설명한다.

공동체 안에서도 무조건적인 허용이 아니라, 거룩한 교제 속에서 진정한 사랑의 공동체가 되어 가는 것이 주님께서 원하시는 참된 공동체일 것이다. 이러한 의미에서 우리 ‘남청연’도 하나님의 평안 가운데 칭찬받는 공동체가 되기를 바란다.

9. 삶의 적용(구체적으로)

마음속에 선하지 못한 마음이 있는지 살펴보아야겠다. 발견되면 보혈의 피로 마음에서 쫓아내야겠다.

 

10. 영적 터치 (단어/구절)

17절: 분쟁을 일으키거나 거치게 하는 자들을 살피고 그들에게서 떠나라

11. 믿음과 회개 및 감사기도로 마무리', 0, true);
INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-04-19', '로마서', '16장 1~10절', '사랑하는 동역자', '(로마서 16장)

1.  내가 겐그레아 교회의 일꾼으로 있는 우리 자매 뵈뵈를 너희에게 추천하노니

2. 너희는 주 안에서 성도들의 합당한 예절로 그를 영접하고 무엇이든지 그에게 소용되는 바를 도와 줄지니 이는 그가 여러 사람과 나의 보호자가 되었음이라

3. 너희는 그리스도 예수 안에서 나의 동역자들인 브리스가와 아굴라에게 문안하라

4. 그들은 내 목숨을 위하여 자기들의 목까지도 내놓았나니 나뿐 아니라 이방인의 모든 교회도 그들에게 감사하느니라

5. 또 저의 집에 있는 교회에도 문안하라 내가 사랑하는 에배네도에게 문안하라 그는 아시아에서 그리스도께 처음 맺은 열매니라

6. 너희를 위하여 많이 수고한 마리아에게 문안하라

7. 내 친척이요 나와 함께 갇혔던 안드로니고와 유니아에게 문안하라 그들은 사도들에게 존중히 여겨지고 또한 나보다 먼저 그리스도 안에 있는 자라

8. 또 주 안에서 내 사랑하는 암블리아에게 문안하라

9. 그리스도 안에서 우리의 동역자인 우르바노와 나의 사랑하는 스다구에게 문안하라

10. 그리스도 안에서 인정함을 받은 아벨레에게 문안하라 아리스도불로의 권속에게 문안하라

