6. 인간 찾기 (관찰)

- 불의한 일이 있을 때 성도 안에서 해결하지 않고 불의한 사람들 앞에서 고발하냐고 묻는 바울

- 믿는 사람들이 지혜롭게 일을 해결하길 바란 바울

- 서로 고발한다는 것은 실패를 의미하며 억울한 일을 당해주고 서로 속아주지 못하냐는 바울

