7. 하나님 찾기 (해석)

- 하나님은 우리를 정죄하지 않으시는 분이시다. 

- 믿음으로 인해 갈등하고 있는 자녀를 돌보시고, 위로해주시는 화평의 하나님이시다. 

8. 인간(해석):

- 부부가 되면 많은 것이 달라진다.

- 그 중 크리스천이 겪는 가장 큰 어려움은 신앙생활일 것이다.

- 믿음이 있다면 서로 다른 신앙관과 신앙의 온도차이로, 믿음이 없다면 신앙생활을 하는 것으로 인해 어려움을 겪게 된다.

- 부부간의 신앙생활에 있어서 지혜와 끈기가 필요하다. 

- 믿는자는 무엇을 하기 보다, 하나님과의 관계를 잘 유지하고, 하나님의 때를 기다리며 신앙생활에 있어서 솔선수범하여야 한다. 

- 이 부분이 참 어렵지만, 포기하지 않는 믿음의 여정을 잘 걸어가야 한다.

- 오랜 시간 아내의 주일 예배를 놓고 고심했다. 자녀로 인해 늘 유치부에 함께 참여하고 있었기 때문이다. 

- 그런데 최근 아내가 온라인으로 1부 주일 예배를 드리기 시작했다. 오랜 시간 참아왔더니 하나님께서 하나님의 때에 움직여 주신 것 같다. 

- 얼마나 감사한 일인가? 내가 움직이지 않아도 하나님께서 일 하신다. 

- 나는 그 분의 여정을 꾸준히, 성실히 이어가기만 하면 된다. 앞으로도 그럴 것이다.   

9. 적용(나): 

- 부부로서 신앙생활을 잘 이어가는 믿음의 동역자가 되도록 기도하여야겠다.

