- 지식은 교만하게 하며 사랑은 덕을 세운다

- 누구든지 하나님을 사랑하면 하나님도 그를 알아준다

- 우상은 아무것도 아니며 하나님은 한 분이시다

- 만물이 하나님에게서 났고 우리도 하나님을 위하여 있다

- 만물이 주 예수 그리스도에게로 말미암고 우리도 그로 말미암아 있다

- 그러나 이 지식이 모두에게 있는 것은 아니므로 어떤 사람은 우상에 대한 습관이 남아있어 우상의 제물로 알고 먹는다

- 그러므로 우리의 자유가 그들에게 걸려 넘어짐이 되지 않도록 조심해야 한다

7.하나님 찾기(해석)

8.인간 찾기(해석)

- 바울은 지식과 사랑을 대조하며 사랑을 실천하여 덕을 세우라고 말한다.

- 우리에게는 우상이 아무것도 아니고 우상의 제물도 아무것도 아니라는 지식이 있다.

- 만물이 주에게서 나오고 주로 말미암고 주께로 돌아감을 아는 지식이 있다.

- 그러나 이 지식이 없는 자들도 많아서 우리가 이 지식으로 교만하여 그들 앞에서 우상의 제물을 먹거나 

- 특히 우상의 집에서 그 제물을 먹는다면, 그것은 그들을 실족하게 하는 것이고 나아가 예수님께 죄를 짓는 것이다.

- 그들을 위해서도 예수님은 십자가를 지셨기 때문이다.

- 우리 주 예수 그리스도께서 구원하신 이들을 우리가 실족시킬 수 있으므로 우리는 그들을 사랑하는 마음으로 우상의 제물을 대할 때 주의해야 한다.

- 바울은 음식이 형제를 실족하게 한다면 영원히 고기를 먹지 않음으로 형제를 실족하게 하지 않겠다고 선언했다.

9.적용(나) 

- 나에게 중요한 것은 지식이 아니라 사랑의 실천이다.

- 내 앞에 있는 사람의 구원을 위해 나는 사랑을 실천하고 덕을 세워야 한다.

- 내 유익보다 남의 유익을 구하는 것 그것이 나의 태도가 돼야 한다.

