4.주제 만들기: 우상 숭배를 하지 말라

5.하나님 찾기(관찰)

- 사람이 감당하지 못할 시험 당함을 허락하지 아니하시고 시험당할 즈음에 또한 피할 길을 내심

6.인간 찾기(관찰)

- 선 줄로 생각하는 자는 넘어질까 조심하라

- 사람이 감당할 시험 밖에는 당한 것이 없음

- 우상 숭배하는 일을 피하라

- 축복의 잔은 그리스도의 피에 참여함이고 떼는 떡은 그리스도의 몸에 참여하는 것이다

7.하나님 찾기(해석)

- 하나님은 신자들을 사랑하시기 때문에 신자가 어려운 시험을 당할 때에 반드시 도움을 주신다.

- 신자는 하나님의 자녀이기 때문에 하나님은 자녀를 보호하고 돌봐주신다.

8.인간 찾기(해석)

- 오늘날 신자들은 출애굽 때 백성들의 죄를 잘 기억하고 교만하여 넘어지지 않기 위해 노력해야 한다.

- 우리가 잘살아갈 수 있는 것은 하나님께서 복 주시고 도와주시기 때문이지 우리가 잘나서가 아니다.

- 이것을 기억하고 늘 하나님을 경외하며 감사하며 살아야 한다. 

- 신자는 감당하지 못할 시험이 있다는 것은 알아야 한다.

- 다만, 하나님의 도우심으로 감당할 수 있게 되는 것이다.

- 그러므로 우리는 감당하기 어려운 시험을 당할 때 반드시 주님을 찾아야 한다.

- 우리는 주님의 도우심 없이는 살아갈 수 없다.

9.적용(나) 

- 내 속에 자리잡고 있는 교만을 말씀과 기도로 억제해야 한다.

- 교만은 소멸되지 않는다.

- 감당하지 못할 시험을 당한 적이 있다. 내 전심이 흔들리는 거대한 시험이었다.

- 절망하여 두려움 속에 살고 있을 때 주님은 놀라우신 능력으로 도우심을 주셨다.

- 나는 바로 극복했으며 나는 그 이후로 주님을 의지할 수 밖에 없는 존재임을 확실히 깨달았다.

