5.하나님 찾기(관찰)

- 몸을 고르게 하여 부족한 지체에게 귀중함을 더하심

- 몸 가운데서 분쟁이 없고 오직 여러 지체가 서로 같이 돌보게 하심

 

6.인간 찾기(관찰)

- 눈과 머리가 중요한 지체이나 손과 발은 쓸데가 없다 할 수 없다

- 한 지체가 고통을 받으면 모든 지체가 고통을 받고, 한 지체가 영광을 얻으면 모든 지체가 즐겁다

- 교회는 그리스도의 몸이요 지체의 각 부분이다

- 성령님은 각 사람에게 다른 은사를 주셨고, 우리는 모든 은사를 가질 수는 없다

7.하나님 찾기(해석)

- 인간의 신체에 필요 없는 부분이 없듯이 한 몸인 교회의 지체(형제)들 또한 필요 없는 지체가 없다.

- 신체의 지체들이 어느 부분이든 꼭 필요한 부분이 있듯이 교회의 지체들 또한 꼭 필요한 부분이 있다.

- 하나님은 교회에 꼭 필요한 은사를 각 사람에게 어울리게 주셨다 

8.인간 찾기(해석)

- 형제 한 명이 고통을 받으면 모두가 고통받고 형제 한 명이 영광을 얻으면 모두가 즐겁다.

- 왜냐하면 교회는 그리스도의 몸이고 형제는 지체의 각 부분이기 때문이다.

- 교회는 한 몸이고 각 지체라는 것을 잘 기억해야 한다.

- 하나님께서 각 사람에게 은사를 다르게 주셨고, 이 은사는 교회에 꼭 필요한 것들이다.

- 몸의 지체들이 모두 소중하듯이 어떤 은사를 받았느냐에 상관없이 교회의 한 사람 한 사람도 다 소중하다.

- 은사는 하나님께서 필요한 대로 주셨기 때문에 받은 은사로 인해 서로 시기하거나 다툴 필요는 없다.

9.적용(나) 

- 그리스도 안에서 형제들은 모두 귀하고 꼭 필요한 존재들이다.

- 우리는 받은 은사를 잘 활용하여 그리스도를 섬기고 형제를 사랑하여 소중히 여겨야 한다.

10.영적 터치(단어/구절)

