6.인간 찾기(관찰)

예언과 방언은 영적 질서 안에서 사용하기를 가르치는 바울  

예언의 은사를 사모하기

방언을 금하지 말것 

7. 하나님 찾기(해석)

8. 인간 찾기(해석)

바울은 교회 안에서의 “질서”를 강조하고 있다. 33절에서는 “하나님은 무질서의 하나님이 아니시요”라고 기록하였고, 40절에서는 “모든 것을 품위 있게 하고 질서 있게 하라”고 말한다. 

은사에 대한 질서를 반복적으로 강조하면서, 특히 예언에 관한 질서를 말하고 있다.

바울은 예언의 은사를 사모하라고 할 정도로 좋은 은사라고 말하면서도 동시에 절제에 대해서도 강조한다. 

공동체 안에서 예언의 은사가 있는 사람들이 동시에 주장하게 되면 듣는 사람이 제대로 이해하지 못할 뿐 아니라, 자칫 서로 경쟁 구도로 흘러가 원래 하나님께서 주신 선물이 사탄의 미끼로 변질될 수도 있음을 인지시키고 있다.

천지 창조를 질서 있게 이루신 하나님의 방식대로 은사가 사용되기를 권면하고 있는 것이다. 교회 안에서 질서를 지키기 위해서는 절제 훈련이 필요하다. 

만약 예배 중 갑자기 성도가 일어나 예언을 외치며 논쟁을 벌인다면 덕스러운 예배가 어려울 것이다. 이때 여성들을 포함하여 모두가 절제할 것을 바울은 말하고 있다.

결국 예언이나 방언과 같은 은사는 모두 귀한 것이지만, 어떠한 동기와 목적으로 사용하느냐가 더욱 중요한 일임이 분명하다.

