5. 하나님 찾기 (관찰)

- 예수님은 우리의 죄를 위해 십자가에 못 박히시고 사흘만에 다시 살아나셔서 수많은 제자들을 만난 후 하늘로 올라가셨다.

6. 인간 찾기 (관찰)

- 전한 복음을 굳건히 지키면 구원 받을 것이라 말하는바울

- 자신이 전한 것은 성경에서 말한대로 예수님께서 오셔서 십자가를 지셨고 다시 살아나셔서 수많은 제자들과 만삭이 되지 못하고 태어난자 같은 자신에게 나타나셨음을 말하는 바울

- 자신은 사도 중에 가장 낮은 자이며, 하나님의 교회를 박해하였으나, 하나님의 은혜로 지금의 내가 되었음을 고백하는 바울

- 자신이 수고한 것은 자신의 힘과 의지로 한 것이 아니라 하나님의 은혜임을 고백하는 바울

