7. 하나님 찾기(해석)

죽음을 이기시고 부활하신 예수님을 찬양한다!

한 사람 아담의 원죄로 인해 모든 인류가 사망에 이르게 되었다. 

그러나 사랑의 하나님께서는 인간을 사랑하셔서, 자신의 독생자 예수 그리스도를 십자가의 희생 제물로 내어 주셨고, 그로 인해 모든 사람에게 생명의 기회를 열어 주셨다.

사랑의 하나님은 창조의 하나님이시며, 동시에 역전의 하나님이시다. 

사망의 권세를 붙들고 있던 사탄을 무너뜨리시고, 결국 창조주 하나님 앞에 무릎 꿇게 하셨다.

주님을 주로 시인하고 인정하는 사람은 더 이상 죽음의 저주 아래에 머물 수 없다. 

그들은 생명의 주님 안에 거하고 있기 때문이다. 빛 가운데 있는 자에게 어둠은 침투할 수 없다.

8. 인간 찾기(해석)

사람들이 가장 두려워하는 것은 결국 죽음의 문제일 것이다. 이 근본적인 죽음의 문제를 인간은 하나님의 사랑으로 해결 받았다. 

그것은 인간의 공로가 아니라 전적인 은혜로 받은 것이다.

이 사실을 깊이 생각해 보면, 신자들은 잠시 머무는 이 땅에서의 고난조차도 충분히 극복할 수 있다. 

오히려 그 은혜를 생각할 때, 주님께 감사하지 못할 이유가 없다는 고백이 자연스럽게 나오게 된다.

