8.인간 찾기(해석)

- 바울과 디모데가 그리스도의 복음과 교회를 위해 얼마나 큰 고난들을 당했는지 알 수 있다.

- 바울은 살 소망이 없어졌다고 느낄 만큼 고난을 당했다.

- 바울과 같이 강력한 믿음의 소유자가 살 소망이 없어졌다고 느낄 정도이면 그 고난의 깊이는 상상을 초월하는 것일 것이다

- 바울은 그 고난을 해석하기를 사람이 자기 자신을 의지하지 않고 하나님만을 의지하게 하신 하나님의 뜻이라고 해석한다

- 그리고 이것을 그리스도로 말미암은 위로라고 말한다

- 고난 받는 상황을 불평하지 않고 하나님만을 의지하는 수단으로 해석하고 나아가 자신의 고난이 다른 이를 위로하는 수단이 된다고 해석하고 있는 것이다

