- 그리고 순종하는지 보려고 이 편지를 썼다고 말함으로써 그 사람을 용서하고 사랑으로 감싸주라는 것을 강조한다

- 내용을 보면 그 사람은 매우 큰 잘못을 저질렀고, 이 것이 교회에 중대한 사안이었음을 알 수 있다.   

