- 잘못한 사람은 벌을 받는 것이 마땅하다. 그러나 죄 지은 사람이 벌을 받고 회개한다면, 용서하고 사랑해야 한다.

- 한편 잘못한 사람을 벌하지 않는 경우도 종종 있다.

- 나는 잘못한 사람에게 벌을 주지 않을 때가 많았다. 성경에서 벌은 하나님께서 주신다고 쓰여 있기 때문이다. 

- 그러나 그것은 나의 무지와 나약함에서 나온 생각과 행동이었다.

- 공동체를 위해서 죄를 지은 자는 반드시 벌을 주어야함을 깨달았다.

- 벌을 받고 진심으로 회개하면 그때 사랑으로 용서하고 위로하는 것이다.

