8.인간 찾기(해석)

- 바울이 성령님의 특별한 지시로 선교 활동을 한 마케도니아 교회가 환난과 가난함 속에서도 풍성한 연보를 했다

- 이것을 통해 마케도니아 교회가 얼마나 큰 은혜를 경험했는지 알 수 있다.

- 큰 은혜를 받은 마케도니아 교회는 구제와 섬기는 일을 하되 자신의 힘에 넘치게 하였다.

- 바울은 이 구제 활동을 은혜라고 표현했는데 이것은 

- 먼저 그들의 활동 자체가 받는 이들이 볼 때 은혜이고, 

- 그들이 받은 은혜의 기쁨으로 하는 활동이므로 은혜이고, 

- 또한 이 활동이 그들에게 유익이 되기 때문에 더욱 은혜인 것이다.

- 마테도니아 교회는 먼저 자신을 주께 드리고, 하나님의 뜻을 따라 바울 일행에게도 주었다.

- 바울은 마케도니아 교회가 경험하고 실천한 이 놀라운 은혜를 고린도 교회도 누리기를 원하며,

- 디도를 통해 이 일을 이미 시작하였다.

- 그리고 편지를 통해 이 은혜의 일을 실천하는데 격려와 응원을 보내고자 하였다.

- 이 은혜를 예수님으로부터 시작되었고, 우리는 은혜 안에서 주님을 본 받으면, 우리 또한 마케도니아 교회와 동일한 은혜를 누리게 될 것이다.

