4.주제 만들기: 연보를 준비하는 자세에 대하여

5.하나님 찾기(관찰)

- 하나님은 즐겨내는 자를 사랑하신다

- 능히 모든 은혜를 넘치게 하신다

- 이렇게 하심은 우리가 모든 일에 항상 모든 것이 넉넉하여, 모든 착한 일을 넘치게 하도록 하심이다

- 너희가 심을 것을 주사 풍성하게 하시고 너희 의의 열매를 더하실 것이다

6.인간 찾기(관찰)

- 고린도교회에 연보를 준비하는 자세에 대하여 말한다

- 연보를 미리 준비하고 있음을 마게도냐에 알렸으며 이것은 내가 마게도냐에 말한 것과 같이 준비되게 하려는 것이다

- 미리 준비되어야 참 연보답고 억지가 아니다

7.하나님 찾기(해석)

- 전능하신 하나님께서는 모든 은혜를 넘치게 하신다.

- 우리에게 주신 은사와 섬김을 통해 우리에게 기쁨이 넘치게 하신다.

- 그것은 모든 개인에게 물질을 주신다는 것은 아니다. 물질은 공동체가 함께 사용할 만큼 또는 그 이상을 주신다.

- 우리는 그것을 균형있게 서로를 위해 사용할 줄 알아야한다.

- 우리 교회만 풍성한 것으로 끝나는 것이 아니라, 가난한 교회와 함께 나누고 섬길 것을 말씀하시고 그것 또한 은혜라고 말씀하신다.

 

- 또한 하나님은 우리에게 심을 것을 주셔서 풍성하게 하시고, 

- 우리에게 의의 열매를 더하신다.

8.인간 찾기(해석)

- 연보를 준비하고 있는 고린도교회를 응원하고 격려하고 있다.

- 연보를 준비하고 있음을 마케도니아 교회에 알림으로 힘을 내도록 하고 있다. 

- 연보를 준비하는 태도에 문제가 없도록

- 은혜 안에서 하도록

- 전능하신 하나님께서 모든 은혜를 주실 것을 말함으로 응원과 격려를 보내고 있다.

- 적게 심는 자는 적게 거두고 많이 심는 자는 많이 거둔다는 물리적 원리와 함께 하나님께서 모든 은혜로 채워주시는 영적 원리를 말함으로 격려한다. 

9.적용(나) 

- 물질 세계와 영적 세계를 살아가는 우리는 물질 세계도 영적 세계도 소홀히 해서는 안 된다.

- 연보라는 것은 물질 세계를 살아가는 우리의 본성을 거스르는 것으로 은혜의 경험 없이는 할 수 없는 것이다.

- 연보는 그래서 어렵다.

- 은혜를 경험한 자만이 연보를 구제를 할 수 있다.

- 그들에게는 기쁨이 있다.

- 은혜와 기쁨 없이 연보를 하는 것은 위험하다. 인색하고 불편한 마음으로 억지로 하거나 남에게 보이기 위해 할 위험이 크기 때문이다.

- 자신의 형편에 맞게 적절하게 연보할 줄 알아야 하는데,

- 부한 사람도 가난한 사람도 자신의 형편에 맞게 연보를 하되,

- 가난한 사람은 많이 할 생각을 줄이고(이 말에 오해가 없기를 바란다..) 누군가 도움을 줄 때 받을 줄 알아야 한다. 나아가 많이 받을 줄도 알아야 한다. 

- 연보를 내는 것도 연보의 혜택을 받는 것도 모든 것은 하나님의 은혜이고 기쁨이다.

10.영적 터치(단어/구절)

11.믿음과 회개 및 감사기도로 마무리

12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);
