- 그런 자들은 바울과 같이 대가 없는 섬김으로 가르치지 않을 것이기에 바울은 계속해서 봉사의 대가를 받지 않겠다고 말한다

- 먼저는 고린도교회를 사랑하기 때문이지만, 그 자들과 구별이 돼야하는 이유도 있기에 더욱 그러했다

- 속이는 자들이 그들의 외모를 자랑했고 고린도교회 신자들이 그것에 속아 그들을 받아들였기에 바울은 자신도 그들에게 모자라지 않음을 말하기 시작한다  

9.적용(나) 

- 교회에는 속이는 자들이 들어올 수 있으므로 신자들은 그들이 외모만 보고 현혹되어서는 안 된다. 

- 속이는 자들을 분별할 수 있기를 바라고, 바울과 같이 헌신해야 할 때는 헌신할 수 있는 사람이 돼야겠다.

10.영적 터치(단어/구절)

