1:감동하는 단어나 구절 찾기(영적 터치)

2026년 04월 04일 

갈라디아서 3장 21절~29절

1.1분기도

2. 본문 읽기(3번)

3. 반복 단어 및 같은 의미 찾기:

율법: 21절(2) 24절 

믿음: 22절(2) 23절(2) 24절 25절 26절 

예수 그리스도: 22절 24절 26절 27절 28절 29절

약속: 21절 22절 29절

초등교사: 24절 25절  

4. 주제:

믿음을 통하여 얻는 의   

5. 하나님 찾기(관찰)

약속대로 하시는 하나님

믿는 자들에게 약속대로 유업을 허락하시는 하나님 

6. 인간 찾기(관찰)

믿음을 통하여 하나님의 아들이 되는 인간들

신자들은 차별 없이 주님 안에서 하나이다. 

 

7. 하나님 찾기(해석)

하나님께서는 자신의 약속을 따라 사도 바울을 통해, 예수 그리스도를 믿는 모든 사람에게 하나님의 아들이 되는 놀라운 특권을 주셨다고 말씀하셨다.

예수 그리스도께서 죄인을 위하여 십자가에서 죽으시고 다시 살아나신 것을 믿는다면, 우리는 더 이상 초등교사와 같은 역할을 하던 율법에 매이지 않게 된다. 대신 참된 자유 안에서 하나님의 유업을 이어받을 자가 된 것이다.

이것이 바로 ‘복음’이다.

복음을 믿는 사람은 구원받음으로써, 마치 초등학교를 졸업하고 더 높은 단계로 나아간 대학생이 된 것과 같다. 

하나님께서는 유대인이나 헬라인이나, 종이나 자유인이나, 남자나 여자나 차별하지 않으시고 누구에게나 동일한 은혜와 특권을 선물로 주셨다.

단지 믿기만 하면 누구나 이 놀라운 복을 누릴 수 있다.

이처럼 큰 은혜를 우리가 받게 된 것은 전적으로 하나님의 사랑과 예수 그리스도의 십자가 희생 덕분이다.

이번 주는 고난주간이고 내일은 부활주일이다. 

이 시간을 통해 특별히 주님의 고난 속에 담긴 깊은 사랑을 더욱 묵상하며, 그 은혜에 감사하는 마음으로 나아가게 된다.

8. 인간 찾기(해석)

9. 적용 (구체적으로)

나의 죄를 위하여 십자가에 죽으신 주님에 대한 희생과 사랑을 깊이 묵상하는 시간을 가져야겠다.

10. 영적 터치 (단어/구절)

26절: 너희가 다 믿음으로 말미암아 그리스도 예수 안에서 하나님의 아들이 되었으니

11. 믿음과 회개 및 감사 기도로 마무리

