9. 적용 (구체적으로)

사랑의 본을 가장 분명하게 보여 주신 분이 바로 독생자 예수 그리스도이시다. 

죄인을 위해 죽으시고 다시 살아나신 주님께서는 지금도 선한 길로 인도하시며 큰 위로와 기쁨이 되신다.

특별히 오늘은 부활주일이다. 

죽으에서 승리하사 다시 살아나신 주님을 더욱 깊이 묵상하며, 찬양을 올려 드려야 하겠다.

