8.인간 찾기(해석)

- 더 이상 할례가 구원의 증표가 아니기 때문에 지키지 말 것을 주장한 것이 십자가의 걸림돌이 되었다

- 할례는 유대교의 핵심 율법으로서 기독교와 유대교가 갈라선 결정적 이유가 되었다

- 율법으로부터 자유함을 받았으나 이 자유를 육체의 기회로 삼지 말고 오직 사랑으로 서로 종 노릇하라고 말한다

- 그러나 사람이 법 없이 본능을 거슬러 서로 사랑함으로 종 노릇한다는 것은 매우 어려운 일이고 불가능한 일이다

  

- 온 율법은 네 이웃 사랑하기를 네 자신 같이 하라 하신 말씀으로 이루어졌다고 말하며 사랑의 중요성을 강조한다

- 그러나 사람이 이웃을 사랑한다는 것은 매우 어려운 일이다

- 그래서 바울은 성령님을 근본적이며 결정적인 해결책으로 제시하며 안내한다

- 너희는 성령을 따라 행하라 그리하면 육체의 욕심을 이루지 아니하리라

- 그리고 성도가 해서는 안 되는 육체의 일을 열거한다

9.적용(나) 

- 사랑은 율법의 완성이다

- 그러나 이 사랑은 하나님께서 부어주셔야만 주어지는 것이다.

- 사람이 육체의 욕심을 이루지 않는 길은 자신의 의지나 준법정신, 또는 도덕심이 아니라,

- 오직 성령님의 인도하심을 받는 것이다.

- 하나님께서 사랑을 부어주시길, 성령님께 인도받는 삶을 살아가길 바라며 간절히 기도해야겠다.

