1:감동하는 단어나 구절 찾기(영적 터치)

2026년 04월 11일 

갈라디아서 6장 1절~10절

1.1분기도

2. 본문 읽기(3번)

3. 반복 단어 및 같은 의미 찾기:

짐을 서로 지라/짐을 질 것이라: 2절 5절

심든지/심는: 7절 8절(2)

거두리라/거두고: 7절 8절 9절

선/ 착한: 9절 10절 

 

4. 주제:

선을 행하는 자의 결실

5. 하나님 찾기(관찰)

영생을 주시는 성령님

6. 인간 찾기(관찰)

신자는 서로의 짐을 나누어지어 그리스도의 법을 성취하라.

성령을 위하여 심는 자는 성령으로 영생을 거둠

7. 하나님 찾기(해석)

8. 인간 찾기(해석)

사도 바울은 그리스도인들에게 선을 행한 후에도 낙심하지 말라고 권면한다. 왜 그는 낙심하지 말라고 했을까?

아마도 이 세상이 결코 만만한 곳이 아님을 알았기 때문일 것이다. 

신자가 기대하고 바라는 대로 모든 일이 쉽게 이루어지지 않는 경우가 많다는 현실을 대부분 잘 알고 있다.

어제, 주님 안에서 사랑하는 제자로부터 슬픈 소식을 들었다. 갑상선암 진단을 받았다는 것이다. 

몇 주 전 몸에 이상이 있어 검사받는다고 했을 때, 좋은 결과가 있기를 바라는 마음으로 생각날 때마다 기도했었다. 그러나 안타깝게 결과는 기대와 달랐다.

그 제자는 평소 하나님을 진심으로 의지하고 사랑하는 사람이다. 그런 소식을 듣고 나니 나 역시 마음 한켠이 무너지는 듯했고, 잠시 힘이 빠지는 것을 느꼈다. 

그러나 하나님의 은혜로 낙심까지 이르지는 않았다.

그 이유는 9절의 “포기하지 아니하면”이라는 말씀이 내 마음에 능력으로 다가왔기 때문이다.

이제 내가 할 일은 분명하다. 때가 찰 때까지 인내하며, 주님께 매달려 기도하는 것이다.

나는 9절의 말씀이 반드시 이루어질 것을 믿는다.

“우리가 선을 행하되 낙심하지 말지니, 포기하지 아니하면 때가 이르매 거두리라.”

9. 적용 (구체적으로)

아는 한 지인(새터민)이 오늘 생일이다. 축하 안부와 선물을 보내야겠다. 무엇보다 기도로 축복해야겠다.

10. 영적 터치 (단어/구절)

9절: 우리가 선을 행하되 낙심하지 말지니 포기하지 아니하면 때가 이르매 거두리라

11. 믿음과 회개 및 감사 기도로 마무리

12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);
INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-07-12', '에베소서', '1장 1~10절', '하늘에 있는 것이나 땅에 있는 것을 통일하실 하나님', '[엡1:1-10]

1 하나님의 뜻으로 말미암아 그리스도 예수의 사도 된 바울은 에베소에 있는 성도들과 그리스도 예수 안에 있는 신실한 자들에게 편지하노니

2 하나님 우리 아버지와 주 예수 그리스도로부터 은혜와 평강이 너희에게 있을지어다

3 찬송하리로다 하나님 곧 우리 주 예수 그리스도의 아버지께서 그리스도 안에서 하늘에 속한 모든 신령한 복을 우리에게 주시되

4 곧 창세 전에 그리스도 안에서 우리를 택하사 우리로 사랑 안에서 그 앞에 거룩하고 흠이 없게 하시려고

5 그 기쁘신 뜻대로 우리를 예정하사 예수 그리스도로 말미암아 자기의 아들들이 되게 하셨으니

6 이는 그가 사랑하시는 자 안에서 우리에게 거저 주시는 바 그의 은혜의 영광을 찬송하게 하려는 것이라

7 우리는 그리스도 안에서 그의 은혜의 풍성함을 따라 그의 피로 말미암아 속량 곧 죄 사함을 받았느니라

8 이는 그가 모든 지혜와 총명을 우리에게 넘치게 하사

9 그 뜻의 비밀을 우리에게 알리신 것이요 그의 기뻐하심을 따라 그리스도 안에서 때가 찬 경륜을 위하여 예정하신 것이니

10 하늘에 있는 것이나 땅에 있는 것이 다 그리스도 안에서 통일되게 하려 하심이라

