5.하나님 찾기(관찰)

- 하나님은 모든 일을 자기의 뜻대로 행하신다

- 하나님의 계획대로 우리는 예정되어 기업이 되었다

- 이것은 그리스도 안에서 전부터 바라던 하나님의 영광의 찬송이 되게 하신 것이다 

- 하나님께서 능력으로 그리스도를 교회의 머리로 삼으심

- 교회는 그리스도의 몸으로서 만물 안에서 만물을 충만하게 하시는 이의 충만함이다

6.인간 찾기(관찰)

- 에베소 교회 형제들도 복음을 듣고 믿어 약속의 성령으로 인치심을 받았다

- 에베소 교회 형제들에게 지혜와 계시의 영을 주시길 기도하는 바울

 

7.하나님 찾기(해석)

- 하나님께서는 자기 뜻대로 우리를 예정하시고 하나님의 상속자가 되게 하셨다

- 이것은 그리스도 안에서 하나님의 영광을 찬송하게 하신 것이다

- 하나님께서는 죄인 된 우리를 그리스도 안에서 구원하시고 상속자, 그리스도와 함께 한 상속자가 되게 하셨다

- 상속자라는 것은 그리스도 안에서 그리스도와 함께 하나님의 자녀가 된다는 것이다.

- 이것을 성령님께서 내주하심으로 보증하시고, 이 확실한 믿음과 감격으로 말미암아 신자는 하나님의 영광을 찬송, 찬미하게 되는 것이다.

-하나님께서는 놀라운 능력으로 그리스도를 교회의 머리로 삼으셨으며, 교회는 그리스도의 몸으로서 하나님의 충만함이 된다.

- 우리 신자는 함께 모여 하나님을 예배하며 교회를 이루고, 교회 안에서 하나님의 충만함을 누리게 되는 것이다.  

8.인간 찾기(해석)

- 신자는 성령님의 인치심을 받은 존재이다

- 그러나 그것으로 멈출 것이 아니라, 더 나아가 지혜와 계시의 영, 곧 성령을 받아야 한다.

- 신자는 이것을 위해 늘 주님을 바라며, 성령 충만함을 바라며, 기도에 힘써야 한다.

