5.하나님 찾기(관찰)

- 그리스도는 우리의 화평이셔서 둘로 하나를 만드심

- 원수 된 것 곧 중간에 막힌 담을 자기 육체로 허셨다

- 이것은 십자가로 이 둘을 한 몸으로 하나님과 화목하게 하려 하심이다

6.인간 찾기(관찰)

- 예수님을 믿기 전 에베소교회 형제들은 이방인이었고 그리스도 밖에 있었음을 말하는 바울

- 예수님의 십자가로 말미암아 에베소교회 형제들은 이방인이 아니라, 성도들과 동일한 시민이요 하나님의 권속이 되었다

- 모퉁잇돌 되신 예수님 안에서 건물마다 서로 연결하여 주 안에서 성전이 되어 간다

7.하나님 찾기(해석)

- 우리 주 예수 그리스도께서는 유대인 뿐만 아니라 에베소교회의 형제들과 같은 이방인도 구원하시기 위해 십자가를 지셨다

- 바울은 이것을 중간에 막힌 담을 자기 육체로 허셨다라고 표현했다

- 예수님의 십자가 사역 없이는 이방인의 구원은 불가능한 것이었기 때문이다

- 이것은 유대인과 이방인을 그리스도 예수 안에서 한 몸이 되어 하나님과 화목하게 하신 것이다

8.인간 찾기(해석)

- 예수님의 십자가 사역으로 말미암아 예베소교회 형제들과 그리스도를 믿는 이방인들도 하나님 나라 시민이요, 하나님의 자녀가 되었다

- 신자는 하나님의 자녀이며 동시에 하나님이 거하실 성전이다

- 신자가 모이면 예수님 안에서 모이고 예수님의 말씀과 그 분을 닮은 삶을 나누게 되는데, 이것이 바로 하나님의 성전이 되어 가는 것이라 할 수 있다.

- 이제 신자가 모여 하나님을 예배하고 찬양하는데 유대인과 이방인의 차별은 없다. 같이 성전으로 지어져갈 뿐이다.

9.적용(나) 

- 중간에 막힌 담을 자기 육체로 허신 예수님을 기억하며,

- 화목하게 하신 것을 거스르지 않도록,

- 신자들과 화목하게 살아가도록 노력해야겠다.

