1:감동하는 단어나 구절 찾기(영적 터치)

2026년 04월 18일 

에베소서 3장 11절~21절

1.1분기도

2. 본문 읽기(3번)

3. 반복 단어 및 같은 의미 찾기:

강건/굳어져서/넘치는/충만: 16절 17절 19절 20절

비노니/구하노라/구하거나: 15절 19절 20절

알고/ 깨달아: 18절 19절

그리스도 예수 안에서: 11절 21절

4. 주제:

속사람을 강건케 하시는 예수

5. 하나님 찾기(관찰)

사랑의 예수

영광 안에 거하시는 예수

신자의 마음속에 계신 예수

6. 인간 찾기(관찰)

바울은 에베소 성도들이 예수 안에서 속사람이 강건하게 되를 간절히 바라며 기도하고 있다. 

7. 하나님 찾기(해석)

하나님의 사랑은 우주보다 크셔서 모든 인간을 품고도 남는 분이시다. 

그러나 그 크신 하나님을 믿는 신자마다 느끼는 사랑의 깊이는 서로 다른 듯하다. 

에베소서 3장 19절에는 “그 너비와 길이와 높이와 깊이가 어떠함을 깨달아”라고 기록되어 있고, 20절에는 “우리 가운데서 역사하시는 능력대로”라고 기록되어 있다. 

능력을 주시는 분은 하나님이시지만, 그것을 받아 누리는 분량은 각 신자의 믿음의 크기에 달린 듯하다.

결국 이 크신 사랑을 깊이 체험하기 위해서는 게으르지 않고, 주를 온전히 신뢰하며 기도하는 태도가 매우 중요함을 깨닫게 된다.

8. 인간 찾기(해석)

사도 바울은 예수님의 모습처럼 영혼을 위해 간절히 기도하는 중보기도의 사역자였다. 

그는 특별히 에베소 교인들을 위하여 그들의 속사람이 강건해지기를 간구하였다. 

바울은 이것이야말로 진정한 능력이며, 인간에게 가장 중요한 요소임을 깊이 알고 있었다.

인생은 잠시 있다 사라지는 안개와 같다. 

이 짧은 세상에서 아무리 부귀영화를 누린다 해도 마음이 행복하지 않고 늘 우울함에 머문다면, 그는 결코 잘 사는 사람이라 할 수 없다. 

반대로 비록 가난할지라도 주님을 믿고 마음의 주인으로 모시며 사는 사람은 이미 모든 만물을 지으신 아버지의 상속자임을 깨달은 자이다. 

그러한 사람은 누구보다도 강건하며 참된 행복을 누리는 사람이다. 

이처럼 속사람이 강건한 삶이야말로 진정으로 복된 삶이라고 말할 수 있다.

9. 적용 (구체적으로)

오늘 기도 시간에 나의 속사람이 더욱 강건해지도록 간절히 기도해야겠다.

10. 영적 터치 (단어/구절)

16절: 속사람을 능력으로 강건하게 하시오며

11. 믿음과 회개 및 감사 기도로 마무리

12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);
INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-07-20', '에베소서', '4장 11~20절', '5. 하나님 찾기 (관찰)', '[엡4:11-20]

11 그가 어떤 사람은 사도로, 어떤 사람은 선지자로, 어떤 사람은 복음 전하는 자로, 어떤 사람은 목사와 교사로 삼으셨으니

12 이는 성도를 온전하게 하여 봉사의 일을 하게 하며 그리스도의 몸을 세우려 하심이라

13 우리가 다 하나님의 아들을 믿는 것과 아는 일에 하나가 되어 온전한 사람을 이루어 그리스도의 장성한 분량이 충만한 데까지 이르리니

14 이는 우리가 이제부터 어린 아이가 되지 아니하여 사람의 속임수와 간사한 유혹에 빠져 온갖 교훈의 풍조에 밀려 요동하지 않게 하려 함이라

15 오직 사랑 안에서 참된 것을 하여 범사에 그에게까지 자랄지라 그는 머리니 곧 그리스도라

16 그에게서 온 몸이 각 마디를 통하여 도움을 받음으로 연결되고 결합되어 각 지체의 분량대로 역사하여 그 몸을 자라게 하며 사랑 안에서 스스로 세우느니라

17 그러므로 내가 이것을 말하며 주 안에서 증언하노니 이제부터 너희는 이방인이 그 마음의 허망한 것으로 행함 같이 행하지 말라

