- 골로새 교회에 편지로 문안하는 바울과 디모데

- 골로새 교회의 믿음과 사랑, 그리고 하늘에 쌓아둔 소망으로 말미암아 하나님께 감사를 드림

- 골로새 교회 형제들이 복음을 듣고 하나님의 은혜를 깨달았고 나아가 열매를 맺어 자라고 있다

- 뿐만 아니라 복음이 전파된 온 천하에서도 복음이 열매를 맺어 자라나고 있다

- 그리스도의 신실한 일꾼인 에바브라를 통해 골로새 교회 형제들의 사랑을 들었다

- 이 말을 듣던 날부터 형제들을 위하여 기도하기를 그치지 않았다 

7.하나님 찾기(해석)

8.인간 찾기(해석)

- 바울은 골로새 교회 형제들의 믿음과 서로 사랑하는 소식을 듣고 기뻐하였다

- 형제들이 믿음을 가지고 서로 사랑하며 복음 안에서 자라나는 것은 바울의 소망이었다

- 골로새 교회 형제들은 복음을 듣고 믿었으며 열매를 맺어 성장하고 있었다

- 뿐만 아니라 복음이 전파된 온 천하에서도 복음이 열매를 맺어 자라나고 있었다

- 이것은 바울이 일생을 바치며 간절히 바라는 소망이었으며 바울을 기쁘게 한 일이었다

 

- 복음은 넓게 확장되는 것이고 깊게 성장하는 것이다

- 신자는 복음 안에서 성장하며 깊어지고, 또한 복음을 확장 시켜야 한다

- 내적 성장 후에 복음을 전파하는 것이 건강한 순서라고 생각된다

- 내적으로 성장하기 전에 복음을 전파하게 되면, 자신도 듣는 자도 괴로워질 수 있다

- 바울은 에바브라에게 골로새 교회 형제들의 믿음과 사랑을 전해듣고, 그들을 위하여 하나님께 기도를 하였다

- 그동안도 하였지만, 에바브라의 말을 통해 감동과 기쁨이 있어 더욱 기도하게 되었을 것이다.

- 사역자에게 복음의 열매가 보이는 것은 아주 큰 기쁨이고, 사역의 동력이 되는 것이다. 

