- 이들은 하나님을 사랑했으며 성령 충만을 받은 자들로 유추된다

- 하나님의 뜻은 신자의 거룩함이다. 신자는 음행을 멀리하고 또한 형제를 해야지 말아야 한다. 모든 일은 주께서 신원하여 주신다.

- 세상을 살다보면 여러 모양으로 억울한 일도 당하고 무례하게 행하는 자들도 만나게 된다. 이 때 형제를 해하고 싶은 마음이 들 수 있지만, 기도하며 인내해야 한다.

- 그것이 오해라면 풀릴 것이고, 정말 악한 자라면 말씀대로 주께서 신원하여 주시기 때문이다.

- 하나님이 우리를 부르심은 세상과 구별되는 거룩함이다. 세상 사람들이 하는 대로 해서는 안된다.

- 이를 저버리고 음행하거나 형제를 해하는 자는 사람을 저버리는 것이 아니라 성령을 주신 하나님을 저버리는 것이다.

- 성령님은 음행과 형제를 해하는 것을 원치 않으시기에 우리에게 거룩한 마음을 주신다.

- 그 마음을 저버리는 것은 성령님을 저버리는 것과 같은 것이다.

- 데살로니가교회 형제들은 하나님을 사랑하고 성령 충만하여 말씀대로 그리고 성령님께서 마음 주시는 대로 서로 사랑하며 살고 있었다.

- 바울은 이들에게 더욱 그러하라고 격려한다.

- 신자는 성령 충만한 가운데 서로 사랑하며 살아가야 한다. 이를 통해 세상은 우리가 예수님의 제자인 것을 알게 되며, 나아가 주님을 바라보게 된다. 

