1.1분기도

2.본문성경 읽기(3번)

3.반복단어(같은의미 단어)

하나님(아버지): 1, 2, 3, 4, 5(2), 7, 8, 11, 12

예수(주 예수 그리스도): 1, 2, 7, 8, 12(2)

