4.주제 만들기: 기도에 대한 가르침

5.하나님 찾기(관찰)

- 모든 사람이 구원을 받으며 진리를 아는 데에 이르기를 원하심

- 예수님께서 모든 사람을 위하여 자기를 대속물로 주심

6.인간 찾기(관찰)

- 기도하는 삶에 대해 말하는 바울

- 모든 사람을 위해 기도하고, 높은 사람을 위해 기도하라

- 남자들이 분노와 다툼이 없이 거룩한 손을 들어 기도하기를 원한다

- 여자들은 단정하게 옷을 입고 소박함과 정절로써 자기를 단장하고 오직 선행으로 단장하기를 원한다

- 하나님을 경외하는 자들에게 마땅한 것이다

7.하나님 찾기(해석)

- 하나님께서모든 사람이 구원받기를 원하신다는 것을 기억하고  우리는 모든 사람의 구원을 위해 기도해야 한다.

- 또한 구원받고 그치는 것이 아니라, 진리를 아는 데까지 자라나야 한다.

- 이방인에게 복음을 전하고 끝나는 것이 아니라, 그들을 말씀과 기도로서 양육해야 한다.

- 함께 생활하며 말씀과 기도의 삶을 공유하고 양육해야 한다. 

- 예수께서는 죄인을 위해 자신을 대속물로 주셨음을 기억하면, 우리가 못할 것이 없다.

8.인간 찾기(해석)

- 믿음의 선한 싸움을 싸우기 위해서는 기도가 필요함을 말한다.

- 우리는 힘과 능력을 하나님께 공급받아야 한다. 복음의 확장은 우리의 능이 아니요, 하나님의 능력에서 나오기 때문이다.

- 기도하되 모든 사람을 위해 기도하고, 높은 사람들을 위해서도 기도하라고 말한다.

- 바울 당시 높은 사람은 교회를 핍박하는 지배국가의 왕과 관리 그리고 유대교 지도자들이었다.

- 자신을 핍박하는 자들을 위해 기도하라는 권면이기에 세상적으로는 이해할 수 없다.

- 그러나 그들이 평안해야 교회가 모든 경건과 단정함으로 고요하고 평안한 생활을 할 수 있고

- 이러한 기도와 태도가 하나님께 선하고 받으실 만한 것이라고 말하면서 

- 하나님께서는 모든 사람을 구원하기를 원하시며 나아가 진리를 아는 데까지 자라길 원하신다는 말로 교회를 가르친다

- 신자는 증오의 대상일지라도, 그의 구원과 평안을 기도해야 한다.

- 예수께서 죄인이었던 우리를 위해 자신을 대속물로 주셨음을 기억하면, 우리가 못할 것이 없다.

- 신자는 모든 곳에서 손을 들어 기도하고 단정하게 옷을 입고 소박함과 정절로써 자기를 단장하고 오직 선행으로 단장해야 한다.

- 신자가 할 일은 말씀과 기도로 능력을 받고 오직 선을 행하는 것이다.

- 이것은 하나님을 경외하는 자들에게 마땅한 것이다.

- 이것은 믿음의 역사로서 과시나 영적 우월감으로 하는 것이 아니요, 사랑의 수고와 때로는 소망의 인내로 하는 것이다.

9.적용(나) 

- 말씀과 기도로 힘을 얻어 불신자들에게 예수님을 비추는 삶을 살고 싶다.

- 성령님께서 나와 대화하는 모든 이의 마음에 예수님을 비추시길 기도한다.

10.영적 터치(단어/구절)

11.믿음과 회개 및 감사기도로 마무리

12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);
