7. 하나님 찾기 (해석) 

8. 인간(해석):

- 사도 바울은 디도에게 편지를 시작하며 자신의 사도 된 이유를 분명하게 밝힌다. 바울은 자신이 누구인지, 왜 부름받았는지, 무엇을 위해 살아가야 하는지를 정확히 알고 있었다.

- 그의 소명은 하나님께서 택하신 자들이 믿음을 갖게 하고, 경건함에 이르며, 진리의 지식을 깨닫고, 영생의 소망을 붙들도록 돕는 것이었다. 

- 하나님으로부터 소명을 깨달은 사람은 흔들리지 않는다. 사도 바울은 감옥에 갇히고 풀려나는 반복된 상황 속에서도 자신의 처지보다 하나님께서 맡기신 사명에 집중했다. 그의 관심은 사람들을 제자 삼고 영생의 소망을 깨닫게 하는 것이었다. 그 결과 바울의 삶과 서신은 2000년이 지난 지금까지도 수많은 사람들에게 도전과 은혜를 주고 있다. 소명이 분명할 때 우리는 환경이 아닌 하나님께서 맡기신 일에 집중할 수 있다. 

- 디도를 그레데에 남겨 장로와 감독을 세우게 한 것을 보면, 바울이 디도를 얼마나 신뢰했는지 알 수 있다. 장로와 감독의 기준은 단순한 봉사 경력이나 헌금 여부가 아니라, 삶과 인격, 그리고 진리를 지킬 수 있는 영적 성숙함이었다. 이 말씀을 통해 오늘날 교회는 어떤 기준으로 일꾼을 세우고 있는지 돌아보게 된다. 또한 그런 지도자들을 세우고 훈련하는 리더의 책임이 얼마나 큰지도 깨닫게 된다. 나 역시 맡겨진 자리에서 더 깨어 있고, 더 노력하며, 본이 되는 삶을 살아가야겠다.

9. 적용(나): 

- 하나님께서 내게 맡겨주신 소명을 깨닫는 삶, 본이 되는 모습을 보이는 삶을 살아가도록 기도해야겠다.

