2026년 06월 24일 

디도서 2장 1절-10절

1.1분기도

2. 본문 읽기(3번)

3. 반복 단어 및 같은 의미찾기:

교훈: 1절 4절 7절 10절

늙은: 2절 3절

말며: 3절 9절

