8. 인간(해석):

- 언제쯤 내 마음은 예수님처럼 넉넉해질 수 있을까.

복음을 알지 못하는 사람들을 진심으로 품고, 선한 마음으로 끝까지 사랑할 수 있을까. 과연 나는 예수님의 사랑을 삶으로 실천하는 사람이 될 수 있을까. 오늘도 스스로에게 질문을 던져 본다.

- 어쩌면 그들의 입장이 되어 보기 전에는 온전히 이해할 수 없을지도 모른다. 그러나 과거의 나를 돌아보면, 하나님을 알지 못했던 그들과 나는 크게 다르지 않았다. 나 역시 죄 가운데 살아갔고, 하나님의 사랑을 깨닫지 못한 채 내 생각과 욕심대로 살아갔다.

- 더 부끄러운 것은 지금의 나이다. 예수님의 사랑을 알고, 복음을 믿는다고 고백하면서도 여전히 사랑보다 판단이 앞서고, 긍휼보다 답답함이 앞설 때가 있다. 그럴 때면 하나님보다 내 기준으로 사람을 바라보고 있는 내 모습을 발견하며 실망하게 된다.

- 그럼에도 나는 낙심하지 않으려 한다. 하나님께서 나를 변화시키는 분이심을 믿기 때문이다. 지금은 부족하고 연약하지만, 성령께서 내 안에서 역사하실 때 나의 죄성은 조금씩 약해지고 예수님의 사랑은 더욱 커질 것을 믿는다.

- 그러므로 오늘도 나는 복음 위에 굳게 서기를 원한다. 때로는 얼굴에 철판을 두른 것처럼 부끄럽고, 넘어질 때도 있겠지만 다시 은혜를 붙들고 일어나야 한다. 내가 여기까지 온 것도 나의 의가 아니라 하나님의 은혜였음을 잊지 않아야 한다.

- 수많은 유혹과 고난 속에서도 성령께서 함께하심을 기억하며, 예수님의 사랑으로 살아가는 사람이 되기를 소망한다. 그리고 언젠가 나의 말보다 삶을 통해 누군가가 예수님을 만나게 되기를 기도한다.

9. 적용(나): 

