8.인간 찾기(해석)

- 빌레몬과 오네시모의 영적 아버지인 바울은 둘에 대해 잘 이해하고 있었다.

- 이들에게 복음을 전했을 뿐만 아니라 함께 생활하며 양육하며 그들의 변화와 성령님께 순종하는 모습을 봤기 때문일 것이다.

- 그래서 바울은 빌레몬이 자신이 말한 것 이상으로 오네시모를 받아들이고 섬길 것을 확신하며 기대했을 것이다.

- 오네시모는 빌레몬에게 용서받고 형제로서 좋은 관계를 유지했을 것으로 보인다. 

- 이 오네시모는 훗날 디모데를 이어 에베소 교회의 목회자가 된다.

- 바울은 비록 감옥에 있지만, 빌레몬과 골로새 교회를 사랑하여 숙소를 마련해 달라고 부탁한다. 바울은 빌레몬과 형제들은 많이 사랑했고, 골로새 교회 형제들 또한 그랬다.

- 어쩌면 편지를 읽는 내내 울고 있었을 빌레몬은 이 글을 읽으며 눈물을 더욱 많이 흘렸을 것이다. 아마도 소리 내어 울었을 것이다. 함께 편지를 읽는 압비아, 아킵보, 골로새 교회 형제들 모두 소리 내어 울었을 것이다.

- 바울, 에바브라, 마가, 아리스다고, 데마, 누가. 이 대단한 믿음의 사람들이 사랑하는 마음으로 함께 문안한다.

- 목숨을 걸고 함께 주님을 믿고 함께 교회를 세우고 한 마음 한 뜻으로 복음을 전한 이들은 서로를 자신 이상으로 사랑했을 것이고, 이들 사이에는 오늘날 우리가 느낄 수 없는 깊은,그 어떤 것이 있었을 것이다.

- 빌레몬의 사랑의 섬김으로 오네시모는 에베소 교회의 목회자가 되고, 아킵보는 골로새 교회의 2대 목회자가 된다.

9.적용(나)

- 목숨을 걸고 우리 주 예수 그리스도를 전하고 한 마음 한 뜻으로 하나님 나라를 확장하는 믿음의 전투를 벌였던 바울 일행과 골로새 교회 형제들. 

- 그리고 그들의 깊은 사랑을 본받고 싶다.

10.영적 터치(단어/구절)

11.믿음과 회개 및 감사기도로 마무리

12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);
INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-09-30', '히브리서', '1장 1~14절', '하나님의 영광의 광채이신 예수', '(히브리서 1장)

1. 옛적에 선지자들을 통하여 여러 부분과 여러 모양으로 우리 조상들에게 말씀하신 하나님이

2. 이 모든 날 마지막에는 아들을 통하여 우리에게 말씀하셨으니 이 아들을 만유의 상속자로 세우시고 또 그로 말미암아 모든 세계를 지으셨느니라

3. 이는 하나님의 영광의 광채시요 그 본체의 형상이시라 그의 능력의 말씀으로 만물을 붙드시며 죄를 정결하게 하는 일을 하시고 높은 곳에 계신 지극히 크신 이의 우편에 앉으셨느니라

4. 그가 천사보다 훨씬 뛰어남은 그들보다 더욱 아름다운 이름을 기업으로 얻으심이니

5. 하나님께서 어느 때에 천사 중 누구에게 너는 내 아들이라 오늘 내가 너를 낳았다 하셨으며 또 다시 나는 그에게 아버지가 되고 그는 내게 아들이 되리라 하셨느냐

6. 또 그가 맏아들을 이끌어 세상에 다시 들어오게 하실 때에 하나님의 모든 천사들은 그에게 경배할지어다 말씀하시며

7. 또 천사들에 관하여는 그는 그의 천사들을 바람으로, 그의 사역자들을 불꽃으로 삼으시느니라 하셨으되

8. 아들에 관하여는 하나님이여 주의 보좌는 영영하며 주의 나라의 규는 공평한 규이니이다

9. 주께서 의를 사랑하시고 불법을 미워하셨으니 그러므로 하나님 곧 주의 하나님이 즐거움의 기름을 주께 부어 주를 동류들보다 뛰어나게 하셨도다 하였고

10. 또 주여 태초에 주께서 땅의 기초를 두셨으며 하늘도 주의 손으로 지으신 바라

11. 그것들은 멸망할 것이나 오직 주는 영존할 것이요 그것들은 다 옷과 같이 낡아지리니

12. 의복처럼 갈아입을 것이요 그것들은 옷과 같이 변할 것이나 주는 여전하여 연대가 다함이 없으리라 하였으나

13. 어느 때에 천사 중 누구에게 내가 네 원수로 네 발등상이 되게 하기까지 너는 내 우편에 앉아 있으라 하셨느냐

14. 모든 천사들은 섬기는 영으로서 구원 받을 상속자들을 위하여 섬기라고 보내심이 아니냐

