6. 인간 찾기(관찰)

저자는 하나님의 아들 예수에 대하여 그의 위대성과 영존성을 표현하고 있다.

7. 하나님 찾기(해석)

히브리서의 저자는 모든 천사보다 뛰어나신 예수 그리스도를 선명하게 증거하고 있다. 

천지를 창조하신 하나님께서 친히 지으신 하늘과 땅도 결국 옷과 같이 낡아지고 변하게 되지만, 오직 주님만은 영원히 변하지 않으시고 영존하신다고 말씀한다.

우리는 눈에 보이는 아름다운 자연을 바라보며 얼마든지 감탄하고 황홀함을 느낄 수 있다. 

그러나 그러한 감동은 시간이 지나면 점차 희미해진다. 또한 세상의 부귀와 영화도 한순간일 것이다. 

반면에 예수 그리스도를 붙들고 그 크신 사랑을 체험한 사람은 지속적으로 주님을 감상하며 찬양하게 된다. 

천지를 창조하신 주님을 통해 자연을 바라보든, 아름다운 자연을 통해 창조주 하나님을 묵상하든, 결국 신자의 마음 중심에는 언제나 예수 그리스도께서 계셔야 함을 히브리서 저자는 분명하게 강조하고 있다.

주님은 하나님의 영광의 광채이시며, 하나님의 본체의 형상이시다. 또한 그 어떤 이름보다 아름답고 존귀한 이름, 곧 "예수"라는 이름 때문에 내 영혼은 깊은 감격과 황홀함을 경험한다.

나의 구세주이시며 나의 주인이신 주님을 더욱 사랑하고, 더욱 찬양하며, 평생 그 이름의 영광을 높여 드리는 삶을 살기를 소망한다.

