4.주제 만들기: 큰 구원과 구원의 창시자 주 예수 그리스도

5.하나님 찾기(관찰)

- 예수님께서 구원을 말씀하심

- 하나님도 성령으로서 구원을 증언하심

- 하나님은 예수님을 잠시 동안 천사보다 못한 존재로 만드셔서 영광과 존귀의 관을 씌우시고 만물을 그 발 아래 복종하게 하심

- 구원의 창시자를 고난을 통해 온전하게 하심

6.인간 찾기(관찰)

- 들은 것에 더운 유념하여 흘러 떠내려가지 않게 해야 한다.

  

7.하나님 찾기(해석)

- 예수님께서 이 땅에 오셔서 하나님 나라 복음에 대하여 말씀하심

- 이것은 히브리서의 수신자인 유대인들에게는 거리끼는 것이었음

- 예수님 없는 구약을 알고 예수님 없는 구약을 믿고 있던 유대인에게 예수님이 하나님의 아들이라는 것과 능력이 없어 십자가에 달려 죽으신 예수님이 구주라는 것은 이해할 수 없는 것이었다.

- 그러나 이 구원은 예수님뿐만 아니라 사도들, 그리고 하나님께서도 성령으로서 증언하셨음을 히브리서 기자는 말하고 있다.

- 예수님께서 부활 승천하시고 보내신 보혜사 성령 하나님이 바로 그 증거이며 직접 증언하신다는 말로 복음과 구원은 확실한 것이라 말하고 있다.

- 하나님께서는 예수님을 잠시 천사보다 못하게 하심으로 십자가에서 죽게 하셨는데, 이 일로 말미암아 예수님은 모든 신자를 구원하는 구원자가 되셨고 영광과 존귀의 관을 쓰셨다.

- 예수님이 잠시 천사보다 못하게 되심은 고난을 통해 구원의 창시자로 온전하게 되기 위함이었다.

- 믿는 유대인들은 이 글을 통해 예수님이 어째서 나약하게 십자가에서 죽으셨는지 이해하는데 도움이 되었을 것이며, 믿지 않는 자 중에서도 머리로 이해하고 믿는 자가 생겼을 것이다.

8.인간 찾기(해석)

- 복음을 듣고 구원을 받았다면 흘러 떠내려가지 않도록, 복음을 가볍게 여기거나 믿음에서 떠나지 않도록 주의해야 한다.

- 천사들을 통하여 말씀(구약)하신 것을 어겨도 공정한 보응을 받았는데, 하나님의 아들의 말씀과 하나님이 성령으로 증언하신 말씀을 어기면 얼마나 큰 보음을 받겠는가.

 

9.적용(나) 

- 신자를 구원하기 위해 예수님은 낮아져 고난을 받으셨다.

- 고난 뒤에 영광과 존귀의 관을 쓰셨다. 이 영광과 존귀의 관은 신자를 구원하는 관이다.

- 예수님은 태초부터, 아니 영원 전부터 하나님의 아들이라는 영광과 존귀의 관을 쓰셨기에 사실 다른 관은 필요가 없는 분이다.

- 그런데 피조물인 신자를 사랑하셔서 우리를 구원하시고 영원히 함께 살고자 신자의 구원자라는 영광과 존귀의 관을 쓰기 위하여 고난을 받으신 것이다.

- 나는 고난을 어떻게 대해야 하는가?

- 신자에게 고난은 영적 성장의 연료요, 하나님의 뜻을 깨닫는 과정일 뿐이다.

- 고난과 기쁨은 바늘과 실처럼 반드시 함께 온다.

- 유대인에게 복음을 전한 히브리서 기자처럼 나도 복음을 거부하는 자들에게 복음을 전해야 한다. 

