- 인간은 스스로 완전해질 수 없다.

- 오직 예수님께서 완전하게 하심으로 완전해 지는 것이다.

- 그러므로 신자는 말씀과 기도에 힘써 하나님의 아들의 영이신 보혜사 성령님(하나님의 영이면서 동시에 예수님의 영이시다)의 도우심을 받아야 한다.

 

- 신자는 구원의 확신을 가지고 하나님의 자녀라는 정체성을 가지고 살아야한다.

- 이것은 세상 유혹과 탐욕을 이길 수 있는 힘이 된다.

