7. 하나님 찾기(해석)

멜기세덱은 의의 왕이며 평강의 왕으로 소개된다. 히브리서 저자는 그를 아버지도 어머니도 없고 족보도 없으며, 시작한 날도 생명의 끝도 기록되지 않은 존재로 표현한다. 

이는 멜기세덱이 실제로 시간과 혈통을 초월한 존재라는 뜻이라기보다, 성경에 그의 출생과 죽음이 기록되지 않았다는 점을 통해 영원한 대제사장이신 예수 그리스도를 예표하기 위함이다.

멜기세덱은 실제 역사 속에서 아브라함을 축복했던 인물이지만, 성경은 그의 삶에 대해 많은 것을 기록하지 않는다. 

분명한 사실은 그가 장차 오실 예수 그리스도를 보여 주는 예표라는 것이다.

예수님은 시간의 제약을 받지 않으시는 영원한 왕이시며, 지금도 살아 계셔서 다스리시는 왕 중의 왕이시다. 

또한 참된 평강과 의를 이루시는 전능하신 하나님이시다. 

예수 그리스도를 믿고 따르는 사람은 세상의 분쟁과 죄의 억압을 넘어 참된 자유와 하나님의 의를 경험하게 된다.

아브라함에게 임했던 멜기세덱의 축복은 이제 영원한 대제사장이신 예수 그리스도를 통하여 모든 믿는 자에게 이어지고 있다. 

그러므로 신자는 어떤 환경과 위치에 있든지 주님 안에서 참된 평강과 하나님 나라의 기쁨을 누릴 수 있음에 감사하게 된다.

주님, 오늘도 세상이 추구하는 성공과 욕망을 따라 살지 않게 하시고, 오직 주님의 성품을 닮아 가며 승리하는 삶을 살게 하옵소서. 

영원한 평강의 왕 되신 예수 그리스도 안에서 참된 기쁨과 자유를 누리게 하시고, 삶의 모든 순간에 주님의 의를 나타내는 믿음의 사람이 되게 하옵소서. 

아멘.

