7. 하나님 찾기(해석)

히브리서 저자는 구원의 근본이시며 인류의 유일한 소망이 되는 예수 그리스도를 본격적으로 드러낸다. 

17절에서 예수님은 멜기세덱의 반차를 따르는 영원한 제사장으로 선포된다. 

예수님은 율법의 기초가 된 아론의 반차를 따르지 않으셨다. 

이는 율법의 계명이 인간을 온전하게 구원하기에는 연약하고 한계가 있었기 때문이다. 

하나님께서는 그 계명을 대신하여 인간을 온전하게 하시는 생명의 복음을 주셨고, 그 복음의 중심에는 예수 그리스도가 계신다.

영원하시며 생명의 능력을 가지신 예수님만이 죄 가운데 있는 인간을 참으로 구원하실 수 있다. 

히브리서의 메시지를 묵상하다 보면 사도 바울이 여러 서신에서 반복하여 강조한 복음의 핵심과도 깊이 연결되어 있음을 느끼게 된다. 

한 분 성령 하나님께서 서로 다른 주의 종들에게 동일한 복음의 진리를 깨닫게 하시고 전하게 하셨다는 사실이 더욱 큰 신뢰와 확신을 준다.

나 또한 오늘도 살아 계시며 나의 영원한 소망이 되시는 예수 그리스도를 더욱 사랑하기를 원한다. 

날마다 그분의 말씀에 순종하며 흔들림 없는 믿음으로 살아가기를 소망한다.

나의 소망이시며 참된 지도자 되시는 주님, 주님을 더욱 사랑하게 하소서. 

세상의 썩어질 동아줄을 붙잡지 않게 하시고, 영원한 안식처와 천국이 되시는 주님만을 바라보며 의지하게 하소서. 

오늘도 생명의 길 되시는 주님을 끝까지 따르게 하옵소서. 아멘.

