- 그리스도의 피가 너희 양심을 죽은 행실에서 깨끗하게 하고 살아 계신 하나님을 섬기게 한다

- 첫 언약 때에 범한 죄에서 속량하려고 죽으사 부르심을 입은 자로 하여금 영원한 기업의 약속을 얻게 하시는 것

6.인간 찾기(관찰)

- 구약시대의 모세도 염소와 송아지의 피를 뿌리며 이것은 하나님께서 너희에게 명하신 언약의 피라고 말함

  

7.하나님 찾기(해석)

- 구약 시대에는 이스라엘의 대제사장이 1년에 한 번 흠이 없는 제물로 제사를 드려 이스라엘 백성의 죄를 속죄했다.

- 이 속죄제는 1년에 한 번씩 꼭 행해야 했고, 이 제물의 피로 이스라엘 백성의 죄를 대신 한 것이다.

- 그러나 이제 흠이 전혀 없으신 하나님의 아들 예수님이 십자가에서 피 흘려 죽으심으로 이것을 믿는 모든 자에게 영원한 속죄를 이루시고 단번에 성소에 들어가셨다. 

- 예수님이 이루신 이 속죄제는 단 한 번의 제사로 영원한 속죄를 약속하는 것으로, 구약 시대에 1년에 한 번 하던 제사와는 다른 것이다.

- 피조물인 염소와 송아지로 드린 제사와 하나님의 아들이신 예수님을 제물로 드린 제사가 어찌 같겠는가?

- 예수님은 우리 인류의 죄를 한 번에 영원히 사하시려고 이 땅에 오셨고 그것을 이루셨다. 할렐루야!

- 우리 주 예수 그리스도의 피는 우리 양심을 죽은 행실에서 깨끗하게 하고 살아 계신 하나님을 섬기게 하는 것이 확실하다.

- 예수님께서 죽으심은 부르심을 입은 자로 하여금 영원한 기업의 약속, 즉 하나님의 자녀로서 영원히 예수님과 함께 살아가는 영광의 약속을 얻게 하셨다.

8.인간 찾기(해석)

- 유언은 유언한 자가 죽은 후에야 효력이 있는 것으로 모세 때에도 송아지와 염소의 피를 사람의 피를 대신하여 언약의 피로 뿌렸음을 언급한다.

