- 언약의 피로서 나를 영원히 속량하시고 영원한 기업을 약속하신 하나님께 감사와 찬양을 올려드리며, 오늘 하루 하나님께서 깨끗하게 하신 양심을 가지고 하나님을 열심히 섬겨야겠다.

- 오늘 하루 맡겨주신 자리에서 선한 일을 열심히 하는 주의 자녀가 돼야한다.

